            def _run_pe_layer_norm_desc_triton(contexts, x_desc, scale_desc, bias_desc, out_desc, attrs):
                if not _has_triton_runtime() or x_desc is None or scale_desc is None or bias_desc is None or out_desc is None:
                    return _triton_native_unsupported("layer_norm requires x/scale/bias/out descriptors")
                try:
                    x_info = _layer_norm_desc_infos(contexts, x_desc)
                    scale_info = _rank4_infos_for_desc(contexts, scale_desc)
                    bias_info = _rank4_infos_for_desc(contexts, bias_desc)
                    out_info = _layer_norm_desc_infos(contexts, out_desc)
                except (KeyError, ValueError, TypeError) as ex:
                    return _triton_native_unsupported(f"layer_norm tensor metadata unsupported: {ex}")
                if x_info["row_counts"] != out_info["row_counts"] or x_info["cols"] != out_info["cols"]:
                    return _triton_native_unsupported(f"layer_norm x/out local shape mismatch: {x_info['local_shapes']} vs {out_info['local_shapes']}")
                axis = int(attrs.get("axis", -1))
                axis = axis if axis >= 0 else x_info["rank"] + axis
                if axis != x_info["rank"] - 1:
                    return _triton_native_unsupported(f"layer_norm native PE-grid path supports last-axis normalization only, got axis={axis} rank={x_info['rank']}")
                cols = int(x_info["cols"])
                if scale_info["max_total"] != cols or bias_info["max_total"] != cols:
                    return _triton_native_unsupported(f"layer_norm scale/bias size mismatch: cols={cols} scale={scale_info['max_total']} bias={bias_info['max_total']}")
                block = _next_power_of_2_int(cols)
                if block > 8192:
                    return _triton_native_unsupported(f"layer_norm cols too large for native Triton block: {cols}")
                max_rows = max(1, int(x_info["max_rows"]))
                _launch_persistent_tile_kernel(contexts, _nncase_pe_layer_norm_kernel, "_nncase_pe_layer_norm_kernel", (block, 1, 1), {"BLOCK": block, "MAX_ROWS": max_rows, "max_rows": int(x_info["max_rows"]), "cols": cols},
                    x_info["ptrs"],
                    _descriptor_pointer_table(contexts, scale_desc),
                    _descriptor_pointer_table(contexts, bias_desc),
                    out_info["ptrs"],
                    x_info["rows"], cols,
                    float(attrs.get("epsilon", 1e-5)),
                    bool(attrs.get("use_mean", True)),
                    x_info["dtype_code"], scale_info["dtype_code"], bias_info["dtype_code"], out_info["dtype_code"],
                    BLOCK=block, MAX_ROWS=max_rows)
                return contexts[0]

            def _run_pe_layer_norm_matmul_desc_triton(contexts, x_desc, scale_desc, bias_desc, rhs_desc, out_desc, attrs):
                if not _has_triton_runtime() or x_desc is None or scale_desc is None or bias_desc is None or rhs_desc is None or out_desc is None:
                    return _triton_native_unsupported("layer_norm_matmul requires x/scale/bias/rhs/out descriptors")
                try:
                    x_info = _layer_norm_desc_infos(contexts, x_desc)
                    scale_info = _rank4_infos_for_desc(contexts, scale_desc)
                    bias_info = _rank4_infos_for_desc(contexts, bias_desc)
                    rhs_info = _rank4_infos_for_desc(contexts, rhs_desc)
                except (KeyError, ValueError, TypeError) as ex:
                    return _triton_native_unsupported(f"layer_norm_matmul tensor metadata unsupported: {ex}")
                axis = int(attrs.get("axis", -1))
                axis = axis if axis >= 0 else x_info["rank"] + axis
                if axis != x_info["rank"] - 1:
                    return _triton_native_unsupported(f"layer_norm_matmul supports last-axis normalization only, got axis={axis} rank={x_info['rank']}")
                cols = int(x_info["cols"])
                if scale_info["max_total"] != cols or bias_info["max_total"] != cols:
                    return _triton_native_unsupported(f"layer_norm_matmul scale/bias size mismatch: cols={cols} scale={scale_info['max_total']} bias={bias_info['max_total']}")
                if len(out_desc.get("shape", [])) == 2 and _desc_allows_local_shape_binding(out_desc):
                    for context, x_rows, rhs_shape in zip(contexts, x_info["row_counts"], rhs_info["local_shapes"]):
                        expected_out_shape = (int(x_rows), int(rhs_shape[3]))
                        _bind_desc_symbols_to_shape(context, out_desc, expected_out_shape, force=True)
                out_info = _rank4_infos_for_desc(contexts, out_desc)
                n_values = []
                for rows, rhs_shape, out_shape in zip(x_info["row_counts"], rhs_info["local_shapes"], out_info["local_shapes"]):
                    rhs_shape = tuple(int(x) for x in rhs_shape)
                    out_shape = tuple(int(x) for x in out_shape)
                    if len(rhs_shape) != 4 or len(out_shape) != 4:
                        return _triton_native_unsupported(
                            f"layer_norm_matmul requires rank4-normalized shapes: rhs={rhs_shape} out={out_shape}")
                    n = int(rhs_shape[3])
                    if int(rhs_shape[2]) != cols or int(out_shape[2]) != int(rows) or int(out_shape[3]) != n:
                        return _triton_native_unsupported(
                            f"layer_norm_matmul PE local shape mismatch: x_rows={x_info['row_counts']} rhs={rhs_info['local_shapes']} out={out_info['local_shapes']}")
                    n_values.append(n)
                store_info = out_info
                out_ptrs = _descriptor_pointer_table(contexts, out_desc)
                if _desc_uses_fp32_partial_storage(out_desc, out_info["type_text"]):
                    store_info = _partial_fp32_info_for_desc(contexts, out_desc, out_info)
                    out_ptrs = store_info["ptrs"]
                block_m, block_n, block_k = _triton_matmul_blocks()
                max_m_tiles = max(1, triton.cdiv(max(x_info["row_counts"]), block_m))
                max_n_tiles = max(1, triton.cdiv(max(n_values), block_n))
                _launch_persistent_tile_kernel(contexts, _nncase_pe_layer_norm_matmul_kernel, "_nncase_pe_layer_norm_matmul_kernel", (block_m, block_n, block_k), {"BLOCK_M": block_m, "BLOCK_N": block_n, "BLOCK_K": block_k, "MAX_M_TILES": int(max_m_tiles), "MAX_N_TILES": int(max_n_tiles), "max_m": int(max(x_info["row_counts"])), "max_n": int(max(n_values)), "k": cols},
                    x_info["ptrs"],
                    _descriptor_pointer_table(contexts, scale_desc),
                    _descriptor_pointer_table(contexts, bias_desc),
                    _descriptor_pointer_table(contexts, rhs_desc),
                    out_ptrs,
                    x_info["rows"], _device_i64_table(n_values), cols,
                    rhs_info["strides"], store_info["strides"],
                    float(attrs.get("epsilon", 1e-5)),
                    bool(attrs.get("use_mean", True)),
                    x_info["dtype_code"], scale_info["dtype_code"], bias_info["dtype_code"], rhs_info["dtype_code"], store_info["dtype_code"],
                    BLOCK_M=block_m, BLOCK_N=block_n, BLOCK_K=block_k, MAX_M_TILES=max_m_tiles, MAX_N_TILES=max_n_tiles)
                return contexts[0]

            def _run_pe_layer_norm_transpose_desc_triton(contexts, x_desc, scale_desc, bias_desc, out_desc, layer_norm_attrs, transpose_attrs):
                if not _has_triton_runtime() or x_desc is None or scale_desc is None or bias_desc is None or out_desc is None:
                    return _triton_native_unsupported("layer_norm_transpose requires x/scale/bias/out descriptors")
                perm = (transpose_attrs or {}).get("perm")
                if perm is None:
                    return _triton_native_unsupported("layer_norm_transpose requires explicit transpose perm")
                try:
                    x_info = _layer_norm_desc_infos(contexts, x_desc)
                    scale_info = _rank4_infos_for_desc(contexts, scale_desc)
                    bias_info = _rank4_infos_for_desc(contexts, bias_desc)
                    out_info = _rank4_infos_for_desc(contexts, out_desc)
                except (KeyError, ValueError, TypeError) as ex:
                    return _triton_native_unsupported(f"layer_norm_transpose metadata unsupported: {ex}")
                rank = int(x_info["rank"])
                if rank != int(out_info["rank"]):
                    return _triton_native_unsupported(f"layer_norm_transpose rank mismatch x={rank} out={out_info['rank']}")
                if len(perm) != rank:
                    return _triton_native_unsupported(f"layer_norm_transpose perm/rank mismatch perm={perm} rank={rank}")
                axis = int((layer_norm_attrs or {}).get("axis", -1))
                axis = axis if axis >= 0 else rank + axis
                if axis != rank - 1:
                    return _triton_native_unsupported(f"layer_norm_transpose supports last-axis normalization only, got axis={axis} rank={rank}")
                pad = 4 - rank
                rank4_perm = tuple(range(pad)) + tuple(int(axis) + pad for axis in perm)
                if sorted(rank4_perm) != [0, 1, 2, 3]:
                    return _triton_native_unsupported(f"layer_norm_transpose invalid rank4 perm={rank4_perm}")
                for src_shape, dst_shape in zip(x_info["local_shapes"], out_info["local_shapes"]):
                    expected = tuple(int(src_shape[axis]) for axis in rank4_perm)
                    if expected != tuple(int(x) for x in dst_shape):
                        return _triton_native_unsupported(
                            f"layer_norm_transpose shape mismatch src={x_info['local_shapes']} dst={out_info['local_shapes']} perm={rank4_perm}")
                cols = int(x_info["cols"])
                if scale_info["max_total"] != cols or bias_info["max_total"] != cols:
                    return _triton_native_unsupported(f"layer_norm_transpose scale/bias size mismatch: cols={cols} scale={scale_info['max_total']} bias={bias_info['max_total']}")
                block = _next_power_of_2_int(cols)
                if block > 8192:
                    return _triton_native_unsupported(f"layer_norm_transpose cols too large for native Triton block: {cols}")
                max_rows = max(1, int(x_info["max_rows"]))
                _launch_persistent_tile_kernel(contexts, _nncase_pe_layer_norm_transpose_rank4_kernel, "_nncase_pe_layer_norm_transpose_rank4_kernel", (block, 1, 1), {"BLOCK": block, "MAX_ROWS": max_rows, "max_rows": int(x_info["max_rows"]), "cols": cols},
                    x_info["ptrs"],
                    _descriptor_pointer_table(contexts, scale_desc),
                    _descriptor_pointer_table(contexts, bias_desc),
                    _descriptor_pointer_table(contexts, out_desc),
                    x_info["rows"], x_info["shapes"], x_info["strides"], out_info["strides"],
                    rank4_perm[0], rank4_perm[1], rank4_perm[2], rank4_perm[3],
                    cols,
                    float((layer_norm_attrs or {}).get("epsilon", 1e-5)),
                    bool((layer_norm_attrs or {}).get("use_mean", True)),
                    x_info["dtype_code"], scale_info["dtype_code"], bias_info["dtype_code"], out_info["dtype_code"],
                    BLOCK=block, MAX_ROWS=max_rows)
                return contexts[0]

            def _run_ccl_rank4_desc_triton(contexts, src_desc, dst_desc, src_type=None, dst_type=None):
                if not _has_triton_runtime() or src_desc is None or dst_desc is None:
                    return _TRITON_NATIVE_UNSUPPORTED
                src_type = src_type if src_type is not None else _desc_distributed_type(src_desc)
                dst_type = dst_type if dst_type is not None else _desc_distributed_type(dst_desc)
                src_info = _rank4_infos_for_desc(contexts, src_desc, src_type)
                dst_info = _rank4_infos_for_desc(contexts, dst_desc, dst_type)
                src_ptrs = _descriptor_pointer_table(contexts, src_desc)
                partial_fp32_info = None
                if _distributed_is_partial(src_type):
                    partial_fp32_info = _partial_fp32_info_for_existing_desc(contexts, src_desc)
                    if partial_fp32_info is not None:
                        src_info = partial_fp32_info
                        src_ptrs = src_info["ptrs"]
                same_shape = src_info["global_shape"] == dst_info["global_shape"]
                same_numel = int(math.prod(src_info["global_shape"])) == int(math.prod(dst_info["global_shape"]))
                same_local_totals = list(src_info.get("local_totals", [])) == list(dst_info.get("local_totals", []))
                if not same_shape and not (_distributed_is_partial(src_type) and same_numel and same_local_totals):
                    return _triton_native_unsupported(
                        f"CCL shape mismatch {src_info['global_shape']} -> {dst_info['global_shape']} for {src_desc.get('name')} -> {dst_desc.get('name')}")
                block = _triton_ccl_block()
                if same_shape:
                    max_tiles = max(1, triton.cdiv(dst_info["max_total"], block))
                    _launch_persistent_tile_kernel(contexts, _nncase_ccl_rank4_kernel, "_nncase_ccl_rank4_kernel", (block, 1, 1), {"BLOCK": block, "MAX_TILES": int(max_tiles), "max_total": int(dst_info["max_total"]), "reduce_partial": bool(_distributed_is_partial(src_type))},
                        src_ptrs,
                        _descriptor_pointer_table(contexts, dst_desc),
                        dst_info["totals"], dst_info["shapes"], dst_info["offsets"],
                        src_info["shapes"], src_info["offsets"],
                        src_info["strides"], dst_info["strides"],
                        dst_info["global_shape"][0], dst_info["global_shape"][1], dst_info["global_shape"][2], dst_info["global_shape"][3],
                        src_info["shard_axis"], dst_info["shard_axis"],
                        _distributed_is_partial(src_type), len(contexts),
                        src_info["dtype_code"], dst_info["dtype_code"], BLOCK=block, MAX_TILES=max_tiles)
                else:
                    max_tiles = max(1, triton.cdiv(dst_info["max_total"], block))
                    _launch_persistent_tile_kernel(contexts, _nncase_ccl_linear_rank4_kernel, "_nncase_ccl_linear_rank4_kernel", (block, 1, 1), {"BLOCK": block, "MAX_TILES": int(max_tiles), "max_total": int(dst_info["max_total"]), "reduce_partial": True},
                        src_ptrs,
                        _descriptor_pointer_table(contexts, dst_desc),
                        dst_info["totals"], src_info["totals"],
                        dst_info["shapes"], src_info["shapes"],
                        dst_info["strides"], src_info["strides"],
                        True, len(contexts),
                        src_info["dtype_code"], dst_info["dtype_code"], BLOCK=block, MAX_TILES=max_tiles)
                if partial_fp32_info is not None:
                    _clear_partial_fp32_desc(contexts, src_desc)
                return contexts[0]

            def _run_tensor_load_ccl_triton(contexts, argument_names, launch_meta):
                dest_name, src_name = argument_names[0], argument_names[1]
                dest_desc = _argument_desc(contexts[0], dest_name, launch_meta, 0)
                if dest_desc is None or not _has_triton_runtime():
                    return _TRITON_NATIVE_UNSUPPORTED
                src = _get_tensor(contexts[0], src_name)
                if not hasattr(src, "data_ptr"):
                    return _TRITON_NATIVE_UNSUPPORTED
                dest_info = _rank4_infos_for_desc(contexts, dest_desc)
                src_shape, src_strides, _ = _rank4_shape_stride(tuple(src.shape), tuple(src.stride()))
                if src_shape != dest_info["global_shape"]:
                    return _TRITON_NATIVE_UNSUPPORTED
                pe_count = len(contexts)
                block = _triton_ccl_block()
                src_ptrs = _device_u64_table([int(src.data_ptr())] * pe_count)
                src_shapes_table = _rank4_static_shape_table(src_shape, pe_count)
                src_offsets_table = _rank4_static_zero_offsets_table(pe_count)
                src_strides_table = _rank4_static_stride_table(src_strides, pe_count)
                max_tiles = max(1, triton.cdiv(dest_info["max_total"], block))
                _launch_persistent_tile_kernel(contexts, _nncase_ccl_rank4_kernel, "_nncase_ccl_rank4_kernel", (block, 1, 1), {"BLOCK": block, "MAX_TILES": int(max_tiles), "max_total": int(dest_info["max_total"]), "tensor_load": True},
                    src_ptrs,
                    _descriptor_pointer_table(contexts, dest_desc),
                    dest_info["totals"], dest_info["shapes"], dest_info["offsets"],
                    src_shapes_table, src_offsets_table,
                    src_strides_table, dest_info["strides"],
                    dest_info["global_shape"][0], dest_info["global_shape"][1], dest_info["global_shape"][2], dest_info["global_shape"][3],
                    -1, dest_info["shard_axis"],
                    False, pe_count,
                    _dtype_code_from_torch(src.dtype), dest_info["dtype_code"], BLOCK=block, MAX_TILES=max_tiles)
                return contexts[0]

            def _run_tensor_store_ccl_triton(contexts, argument_names, launch_meta):
                src_name, dest_name = argument_names[0], argument_names[1]
                src_desc = _argument_desc(contexts[0], src_name, launch_meta, 0)
                dest_desc = _argument_desc(contexts[0], dest_name, launch_meta, 1)
                if src_desc is not None and dest_desc is not None:
                    return _run_ccl_rank4_desc_triton(contexts, src_desc, dest_desc, _desc_distributed_type(src_desc), _desc_distributed_type(dest_desc))
                return _TRITON_NATIVE_UNSUPPORTED

            def _run_gather_reduce_scatter_ccl_triton(contexts, argument_names, launch_meta):
                attrs = (launch_meta or {}).get("op_attrs", {})
                src_desc = _argument_desc(contexts[0], argument_names[0], launch_meta, 0)
                dst_desc = _argument_desc(contexts[0], argument_names[1], launch_meta, 1)
                return _run_ccl_rank4_desc_triton(
                    contexts,
                    src_desc,
                    dst_desc,
                    attrs.get("in_type") or (src_desc and _desc_distributed_type(src_desc)),
                    attrs.get("out_type") or (dst_desc and _desc_distributed_type(dst_desc)))

            def _is_elided_ccl_tail_launch(launch_meta):
                return bool(((launch_meta or {}).get("op_attrs", {}) or {}).get("elided_by_ccl_tail", False))

            def _ccl_tail_launch_meta(tail_meta):
                return {
                    "kind": "collective",
                    "op_name": "gather_reduce_scatter",
                    "ordinal": int(tail_meta.get("source_ordinal", -1)),
                    "arguments": list(tail_meta.get("arguments", [])),
                    "buffer_arguments": dict(tail_meta.get("buffer_arguments", {}) or {}),
                    "op_attrs": dict(tail_meta.get("op_attrs", {}) or {}),
                    "requires_collective": True,
                }

            def _run_ccl_tail_barrier(contexts, tail_meta):
                if not contexts or not _has_triton_runtime():
                    return
                scratch_pool = int(contexts[0].get("ccl_scratch_pool", 0) or 0)
                scratch_bytes = int(contexts[0].get("ccl_scratch_bytes", 0) or 0)
                site = int(tail_meta.get("site", 0) or 0)
                offset = site * 16
                if scratch_pool == 0 or scratch_bytes < offset + 16:
                    return
                generation = int(contexts[0].setdefault("ccl_tail_generations", {}).get(site, 0))
                scratch_tensor = _tensor_from_pointer(scratch_pool + offset, _require_torch().int64, (2,), (1,))
                _launch_persistent_tile_kernel(
                    contexts,
                    _nncase_ccl_tail_barrier_kernel,
                    "_nncase_ccl_tail_barrier_kernel",
                    (1, 1, 1),
                    {"ccl_tail_barrier": True, "site": site},
                    scratch_tensor,
                    expected=len(contexts),
                    generation=generation)
                for context in contexts:
                    context.setdefault("ccl_tail_generations", {})[site] = generation + 1

            def _run_fused_ccl_tail(contexts, producer_launch_meta, tail_meta):
                if not _fused_kernel_allows_ccl_fusion():
                    return _TRITON_NATIVE_UNSUPPORTED
                if not contexts:
                    return _TRITON_NATIVE_UNSUPPORTED
                _run_ccl_tail_barrier(contexts, tail_meta)
                tail_launch_meta = _ccl_tail_launch_meta(tail_meta)
                result = _run_gather_reduce_scatter_ccl_triton(
                    contexts,
                    list(tail_launch_meta.get("arguments", [])),
                    tail_launch_meta)
                if result is _TRITON_NATIVE_UNSUPPORTED:
                    return result
                contexts[0].setdefault("launches", []).append({
                    "kind": "collective",
                    "op_name": tail_meta.get("op_name", "ccl_tail.grs"),
                    "arguments": list(tail_launch_meta.get("arguments", [])),
                    "separate": False,
                    "metadata": tail_launch_meta,
                    "producer": producer_launch_meta,
                })
                return result

            def _run_fused_ccl_tails(contexts, producer_launch_meta):
                result = None
                for tail_meta in (((producer_launch_meta or {}).get("op_attrs", {}) or {}).get("ccl_tails", []) or []):
                    result = _run_fused_ccl_tail(contexts, producer_launch_meta, tail_meta)
                    if result is _TRITON_NATIVE_UNSUPPORTED and _triton_native_required():
                        reason = globals().get("_LAST_TRITON_NATIVE_UNSUPPORTED_REASON", "native CCL tail returned unsupported")
                        raise RuntimeError(f"CUDA/Triton strict mode requires fused CCL tail for {tail_meta.get('op_name')}: {reason}")
                return result

            def _try_execute_triton_multi_pe_native_launch(contexts, kind, op_name, argument_names, launch_meta):
                if not _triton_native_enabled() or not contexts:
                    return _TRITON_NATIVE_UNSUPPORTED
                context = contexts[0]
                attrs = (launch_meta or {}).get("op_attrs", {})
                descs = [_argument_desc(context, name, launch_meta, index) for index, name in enumerate(argument_names)]
                if op_name.startswith("fusion.cuda.flash_attention"):
                    if len(descs) < 4:
                        return _triton_native_unsupported("flash_attention fusion requires q, k, v, and output descriptors")
                    return _run_pe_flash_attention_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3], attrs, descs[4] if len(descs) > 4 else None)
                if op_name.startswith("fusion.cuda.swish_mul"):
                    if len(descs) < 3:
                        return _triton_native_unsupported("swish_mul fusion requires gate, up, and output descriptors")
                    return _run_pe_swish_mul_desc_triton(contexts, descs[0], descs[1], descs[2])
                if op_name.startswith("fusion.cuda.matmul_swish_mul"):
                    if len(descs) < 4:
                        return _triton_native_unsupported("matmul_swish_mul fusion requires gate, lhs, rhs, and output descriptors")
                    return _run_pe_matmul_swish_mul_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3])
                if op_name.startswith("fusion.cuda.silu_mul_matmul"):
                    if len(descs) < 4:
                        return _triton_native_unsupported("silu_mul_matmul fusion requires gate, up, rhs, and output descriptors")
                    return _run_pe_silu_mul_matmul_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3])
                if op_name.startswith("fusion.cuda.matmul_mul_matmul"):
                    if len(descs) < 5:
                        return _triton_native_unsupported("matmul_mul_matmul fusion requires gate, lhs, up rhs, down rhs, and output descriptors")
                    return _run_pe_matmul_mul_matmul_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3], descs[4])
                if op_name.startswith("fusion.cuda.matmul_silu_matmul_mul_matmul"):
                    if len(descs) < 5:
                        return _triton_native_unsupported("matmul_silu_matmul_mul_matmul fusion requires lhs, gate rhs, up rhs, down rhs, and output descriptors")
                    return _run_pe_matmul_silu_matmul_mul_matmul_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3], descs[4])
                if op_name.startswith("fusion.cuda.layer_norm_transpose"):
                    if len(descs) < 4:
                        return _triton_native_unsupported("layer_norm_transpose fusion requires input, scale, bias, and output descriptors")
                    match = re.match(r"fusion\.cuda\.layer_norm_transpose_a(?P<axis>-?\d+)_e(?P<epsilon>[-+0-9.eE]+)_m(?P<use_mean>[01])_p(?P<perm>[0-9_]+)_\d+$", op_name)
                    if match is None:
                        return _triton_native_unsupported(f"layer_norm_transpose fusion name does not encode attrs: {op_name}")
                    layer_norm_attrs = {
                        "axis": int(match.group("axis")),
                        "epsilon": float(match.group("epsilon")),
                        "use_mean": match.group("use_mean") == "1",
                    }
                    transpose_attrs = {"perm": [int(part) for part in match.group("perm").split("_") if part != ""]}
                    return _run_pe_layer_norm_transpose_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3], layer_norm_attrs, transpose_attrs)
                if op_name.startswith("fusion.cuda.layer_norm_matmul"):
                    if len(descs) < 5:
                        return _triton_native_unsupported("layer_norm_matmul fusion requires input, scale, bias, rhs, and output descriptors")
                    match = re.match(r"fusion\.cuda\.layer_norm_matmul_a(?P<axis>-?\d+)_e(?P<epsilon>[-+0-9.eE]+)_m(?P<use_mean>[01])_\d+$", op_name)
                    if match is None:
                        return _triton_native_unsupported(f"layer_norm_matmul fusion name does not encode attrs: {op_name}")
                    layer_norm_attrs = {
                        "axis": int(match.group("axis")),
                        "epsilon": float(match.group("epsilon")),
                        "use_mean": match.group("use_mean") == "1",
                    }
                    return _run_pe_layer_norm_matmul_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3], descs[4], layer_norm_attrs)
                if op_name.startswith("fusion.cuda.mul_cos"):
                    if len(descs) < 3:
                        return _triton_native_unsupported("mul_cos fusion requires lhs, rhs, and output descriptors")
                    return _run_pe_mul_unary_desc_triton(contexts, descs[0], descs[1], descs[2], 1)
                if op_name.startswith("fusion.cuda.mul_sin"):
                    if len(descs) < 3:
                        return _triton_native_unsupported("mul_sin fusion requires lhs, rhs, and output descriptors")
                    return _run_pe_mul_unary_desc_triton(contexts, descs[0], descs[1], descs[2], 2)
                if op_name.startswith("fusion.cuda.rope"):
                    if len(descs) < 4:
                        return _triton_native_unsupported("rope fusion requires input, cos, sin, and output descriptors")
                    return _run_pe_rope_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3])
                if op_name == "tensor_load":
                    return _run_tensor_load_ccl_triton(contexts, argument_names, launch_meta)
                if op_name == "tensor_store":
                    return _run_tensor_store_ccl_triton(contexts, argument_names, launch_meta)
                if op_name == "gather_reduce_scatter":
                    return _run_gather_reduce_scatter_ccl_triton(contexts, argument_names, launch_meta)
                if op_name == "memcopy":
                    if _desc_is_reference(descs[0] if descs else None) or _desc_is_reference(descs[1] if len(descs) > 1 else None):
                        return _run_reference_memcopy_multi(contexts, argument_names[0], argument_names[1], descs[0] if descs else None, descs[1] if len(descs) > 1 else None)
                    return _run_pe_copy_desc_triton(contexts, descs[1] if len(descs) > 1 else None, descs[0] if descs else None)
                if op_name == "gather":
                    return _run_pe_gather_desc_triton(contexts, descs[0], descs[1], descs[2], attrs)
                if op_name == "matmul":
                    return _run_pe_matmul_desc_triton(contexts, descs[0], descs[1], descs[2], attrs)
                if op_name == "transpose":
                    return _run_pe_transpose_desc_triton(contexts, descs[0], descs[1], attrs)
                if op_name in ("ro_pe", "rope"):
                    return _run_pe_rope_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3])
                if op_name == "vectorized_layer_norm":
                    return _run_pe_layer_norm_desc_triton(contexts, descs[0], descs[1], descs[2], descs[4] if len(descs) > 4 else None, attrs)
                if op_name == "get_position_ids":
                    return _run_pe_position_ids_desc_triton(contexts, descs[1] if len(descs) > 1 else None)
                if op_name in ("update_paged_attention_kvcache", "update_paged_attention_kv_cache"):
                    return _run_pe_update_kv_desc_triton(contexts, descs[0] if descs else None, attrs, argument_names[1] if len(argument_names) > 1 else None)
                if op_name == "paged_attention":
                    return _run_pe_paged_attention_desc_triton(contexts, descs[0] if descs else None, descs[3] if len(descs) > 3 else None, descs[4] if len(descs) > 4 else None, attrs, argument_names[1] if len(argument_names) > 1 else None)
                if op_name == "concat":
                    return _run_pe_concat_desc_triton(contexts, descs[:-1], descs[-1] if descs else None, attrs)
                if op_name == "swish":
                    return _run_pe_unary_desc_triton(contexts, descs[0], descs[1] if len(descs) > 1 else None, 3, float(attrs.get("beta", 1.0)))
                if op_name == "elementwise.cast":
                    return _run_pe_copy_desc_triton(contexts, descs[0], descs[1] if len(descs) > 1 else None)
                if op_name == "elementwise.add":
                    return _run_pe_binary_desc_triton(contexts, descs[0], descs[1], descs[2], 0)
                if op_name == "elementwise.mul":
                    return _run_pe_binary_desc_triton(contexts, descs[0], descs[1], descs[2], 1)
                if op_name == "elementwise.compare.equal":
                    return _run_pe_binary_desc_triton(contexts, descs[0], descs[1], descs[2], 2)
                if op_name == "elementwise.where":
                    return _run_pe_where_desc_triton(contexts, descs[0], descs[1], descs[2], descs[3])
                if op_name == "elementwise.cos":
                    return _run_pe_unary_desc_triton(contexts, descs[0], descs[1], 1)
                if op_name == "elementwise.sin":
                    return _run_pe_unary_desc_triton(contexts, descs[0], descs[1], 2)
                return _TRITON_NATIVE_UNSUPPORTED

            def _memory_key(desc):
                memory = (desc or {}).get("memory", {})
                def normalize(value):
                    if isinstance(value, dict):
                        if value.get("kind") == "fixed":
                            return str(value.get("value", 0))
                        return json.dumps(value, sort_keys=True)
                    return str(value)
                return (
                    memory.get("location"),
                    str(memory.get("hierarchy", 0)),
                    normalize(memory.get("base_start", 0)),
                    normalize(memory.get("span_start_bytes", 0)),
                    normalize(memory.get("span_size_bytes", 0)),
                )

            def _launch_argument_index(launch_meta, key, desc):
                match = re.fullmatch(r"arg(\d+)", str(key or ""))
                if match:
                    return int(match.group(1))
                name = (desc or {}).get("name")
                if not name:
                    return None
                matches = [index for index, arg in enumerate((launch_meta or {}).get("arguments", [])) if arg == name]
                return matches[0] if len(matches) == 1 else None

            def _launch_output_indices(launch_meta):
                op_name = (launch_meta or {}).get("op_name")
                arguments = list((launch_meta or {}).get("arguments", []))
                if str(op_name).startswith("fusion.cuda.flash_attention"):
                    return {3} if len(arguments) > 3 else set()
                if str(op_name).startswith("fusion.cuda.swish_mul"):
                    return {2} if len(arguments) > 2 else set()
                if str(op_name).startswith("fusion.cuda.matmul_swish_mul"):
                    return {3} if len(arguments) > 3 else set()
                if str(op_name).startswith("fusion.cuda.silu_mul_matmul"):
                    return {3} if len(arguments) > 3 else set()
                if str(op_name).startswith("fusion.cuda.matmul_mul_matmul"):
                    return {4} if len(arguments) > 4 else set()
                if str(op_name).startswith("fusion.cuda.matmul_silu_matmul_mul_matmul"):
                    return {4} if len(arguments) > 4 else set()
                if str(op_name).startswith("fusion.cuda.layer_norm_transpose"):
                    return {3} if len(arguments) > 3 else set()
                if str(op_name).startswith("fusion.cuda.layer_norm_matmul"):
                    return {4} if len(arguments) > 4 else set()
                if str(op_name).startswith("fusion.cuda.mul_cos"):
                    return {2} if len(arguments) > 2 else set()
                if str(op_name).startswith("fusion.cuda.mul_sin"):
                    return {2} if len(arguments) > 2 else set()
                if str(op_name).startswith("fusion.cuda.rope"):
                    return {3} if len(arguments) > 3 else set()
                if op_name == "matmul":
                    return {2}
                if op_name in ("softmax", "vectorized_softmax"):
                    return {1}
                if op_name == "tensor_load":
                    return {0}
                if op_name == "tensor_store":
                    return {1}
                if op_name == "gather_reduce_scatter":
                    return {1}
                if op_name in ("update_paged_attention_kvcache", "update_paged_attention_kv_cache"):
                    return set()
                if op_name == "paged_attention":
                    return {4}
                if op_name == "concat":
                    return {len(arguments) - 1} if arguments else set()
                if (launch_meta or {}).get("kind") == "function":
                    function_id = __nncase_triton_metadata__.get("function_ids", {}).get(op_name)
                    callee_meta = _get_function_metadata(function_id) if function_id is not None else {}
                    parameters = list(callee_meta.get("parameters", []))
                    filtered = _filter_function_argument_items(arguments)
                    outputs = set()
                    for ordinal, (arg_index, _) in enumerate(filtered):
                        if ordinal < len(parameters) and "Out" in str(parameters[ordinal]):
                            outputs.add(int(arg_index))
                    return outputs
                return {len(arguments) - 1} if arguments else set()

            def _is_launch_output_desc(launch_meta, key, desc):
                index = _launch_argument_index(launch_meta, key, desc)
                if index is None:
                    return str(key or "") in ("output", "dest")
                return int(index) in _launch_output_indices(launch_meta)

            def _prepare_partial_state_for_outputs(contexts, launch_meta):
                input_alias_keys = set()
                for key, desc in (launch_meta or {}).get("buffer_arguments", {}).items():
                    if isinstance(desc, dict) and desc.get("name") and not _is_launch_output_desc(launch_meta, key, desc):
                        input_alias_keys.add(_memory_key(desc))
                for key, desc in (launch_meta or {}).get("buffer_arguments", {}).items():
                    if not isinstance(desc, dict) or not desc.get("name") or not _is_launch_output_desc(launch_meta, key, desc):
                        continue
                    alias_key = _memory_key(desc)
                    if alias_key in input_alias_keys:
                        continue
                    for context in contexts:
                        context.setdefault("partial_aliases", {}).pop(alias_key, None)
                        context.setdefault("partial_fp32_values", {}).pop(alias_key, None)
                        context.setdefault("materialized_partial_inputs", set()).discard(alias_key)

            def _record_partial_aliases(contexts, launch_meta):
                for key, desc in (launch_meta or {}).get("buffer_arguments", {}).items():
                    if not isinstance(desc, dict) or not desc.get("name") or not _is_launch_output_desc(launch_meta, key, desc):
                        continue
                    alias_key = _memory_key(desc)
                    if _distributed_is_partial(_desc_distributed_type(desc)):
                        for context in contexts:
                            context.setdefault("partial_aliases", {})[alias_key] = desc
                            context.setdefault("materialized_partial_inputs", set()).discard(alias_key)
                    else:
                        for context in contexts:
                            context.setdefault("partial_aliases", {}).pop(alias_key, None)
                            context.setdefault("partial_fp32_values", {}).pop(alias_key, None)
                            context.setdefault("materialized_partial_inputs", set()).discard(alias_key)

            def _materialize_partial_aliases(contexts, launch_meta):
                if not contexts:
                    return
                partial_aliases = contexts[0].setdefault("partial_aliases", {})
                for key, desc in (launch_meta or {}).get("buffer_arguments", {}).items():
                    if not isinstance(desc, dict) or not desc.get("name"):
                        continue
                    if _distributed_is_partial(_desc_distributed_type(desc)):
                        continue
                    if _is_launch_output_desc(launch_meta, key, desc):
                        continue
                    alias_key = _memory_key(desc)
                    partial_desc = partial_aliases.get(alias_key)
                    if partial_desc is None:
                        continue
                    if alias_key == _memory_key(partial_desc) and _partial_fp32_info_for_existing_desc(contexts, partial_desc) is None:
                        if _triton_native_required():
                            raise RuntimeError(
                                f"CUDA/Triton strict mode requires fp32 partial storage before in-place alias materialization "
                                f"for {partial_desc.get('name')} -> {desc.get('name')}")
                    result = _run_ccl_rank4_desc_triton(
                        contexts,
                        partial_desc,
                        desc,
                        _desc_distributed_type(partial_desc),
                        _desc_distributed_type(desc))
                    if result is _TRITON_NATIVE_UNSUPPORTED:
                        if _triton_native_required():
                            reason = globals().get("_LAST_TRITON_NATIVE_UNSUPPORTED_REASON", "native CCL materialization returned unsupported")
                            raise RuntimeError(
                                f"CUDA/Triton strict mode requires a native CCL materialization for Partial alias "
                                f"{partial_desc.get('name')} -> {desc.get('name')}: {reason}")
                        full = _materialize_global_tensor(contexts, partial_desc.get("name"), partial_desc, _desc_distributed_type(partial_desc))
                        target_shape = _append_vector_lanes_to_shape(_resolve_shape(contexts[0], desc), _desc_vector_lanes(desc, _desc_distributed_type(desc)))
                        if int(full.numel()) != int(math.prod(target_shape)):
                            continue
                        if tuple(full.shape) != tuple(target_shape):
                            full = full.reshape(tuple(target_shape))
                        _write_distributed_tensor(contexts, desc.get("name"), full, desc, _desc_distributed_type(desc))
                    for context in contexts:
                        context.setdefault("partial_aliases", {}).pop(alias_key, None)

            def _materialize_partial_inputs(contexts, launch_meta):
                if not contexts or (launch_meta or {}).get("op_name") == "gather_reduce_scatter":
                    return
                partial_aliases = contexts[0].setdefault("partial_aliases", {})
                for key, desc in (launch_meta or {}).get("buffer_arguments", {}).items():
                    if not isinstance(desc, dict) or not desc.get("name"):
                        continue
                    if not _distributed_is_partial(_desc_distributed_type(desc)):
                        continue
                    if _is_launch_output_desc(launch_meta, key, desc):
                        continue
                    alias_key = _memory_key(desc)
                    partial_desc = partial_aliases.get(alias_key, desc)
                    if alias_key == _memory_key(partial_desc) and _partial_fp32_info_for_existing_desc(contexts, partial_desc) is None:
                        if _triton_native_required():
                            raise RuntimeError(
                                f"CUDA/Triton strict mode requires fp32 partial storage before in-place Partial input materialization "
                                f"for {partial_desc.get('name')}")
                    result = _run_ccl_rank4_desc_triton(
                        contexts,
                        partial_desc,
                        desc,
                        _desc_distributed_type(partial_desc),
                        _distributed_as_nonpartial(_desc_distributed_type(desc)))
                    if result is _TRITON_NATIVE_UNSUPPORTED:
                        if _triton_native_required():
                            reason = globals().get("_LAST_TRITON_NATIVE_UNSUPPORTED_REASON", "native CCL materialization returned unsupported")
                            raise RuntimeError(
                                f"CUDA/Triton strict mode requires a native CCL materialization for Partial input "
                                f"{partial_desc.get('name')} -> {desc.get('name')}: {reason}")
                        full = _materialize_global_tensor(contexts, partial_desc.get("name"), partial_desc, _desc_distributed_type(partial_desc))
                        target_shape = _append_vector_lanes_to_shape(_resolve_shape(contexts[0], desc), _desc_vector_lanes(desc, _desc_distributed_type(desc)))
                        if int(full.numel()) == int(math.prod(target_shape)) and tuple(full.shape) != tuple(target_shape):
                            full = full.reshape(tuple(target_shape))
                        _write_distributed_tensor(contexts, desc.get("name"), full, desc, _desc_distributed_type(desc))
                    for context in contexts:
                        context.setdefault("partial_aliases", {}).pop(alias_key, None)
                        context.setdefault("materialized_partial_inputs", set()).add(alias_key)

            def _run_tensor_load_multi(contexts, argument_names, launch_meta):
                dest_name, src_name = argument_names[0], argument_names[1]
                dest_desc = _find_launch_buffer_desc(contexts[0], dest_name, launch_meta, 0)
                if dest_desc is None:
                    return [_execute_launch("boxing", "tensor_load", context, argument_names, True, launch_meta) for context in contexts]
                src = _get_tensor(contexts[0], src_name)
                return _write_distributed_tensor(contexts, dest_name, src, dest_desc, _desc_distributed_type(dest_desc))

            def _run_tensor_store_multi(contexts, argument_names, launch_meta):
                src_name, dest_name = argument_names[0], argument_names[1]
                src_desc = _find_launch_buffer_desc(contexts[0], src_name, launch_meta, 0)
                if src_desc is None:
                    return [_execute_launch("boxing", "tensor_store", context, argument_names, True, launch_meta) for context in contexts]
                full = _materialize_global_tensor(contexts, src_name, src_desc, _desc_distributed_type(src_desc))
                return _write_tensor(contexts[0], dest_name, full)

            def _run_gather_reduce_scatter_multi(contexts, argument_names, launch_meta):
                attrs = (launch_meta or {}).get("op_attrs", {})
                src_name, dest_name = argument_names[0], argument_names[1]
                src_desc = _find_launch_buffer_desc(contexts[0], src_name, launch_meta, 0)
                dest_desc = _find_launch_buffer_desc(contexts[0], dest_name, launch_meta, 1)
                if src_desc is None or dest_desc is None:
                    return [_execute_launch("collective", "gather_reduce_scatter", context, argument_names, True, launch_meta) for context in contexts]
                full = _materialize_global_tensor(contexts, src_name, src_desc, attrs.get("in_type") or _desc_distributed_type(src_desc))
                return _write_distributed_tensor(contexts, dest_name, full, dest_desc, attrs.get("out_type") or _desc_distributed_type(dest_desc))

            def _run_update_kv_multi(contexts, argument_names, launch_meta):
                attrs = (launch_meta or {}).get("op_attrs", {})
                src_name = argument_names[0]
                src_desc = _find_launch_buffer_desc(contexts[0], src_name, launch_meta, 0)
                if src_desc is None:
                    return _run_update_kv(contexts[0], argument_names, attrs)
                full = _materialize_global_tensor(contexts, src_name, src_desc, _desc_distributed_type(src_desc))
                temp_context = dict(contexts[0])
                temp_context["values"] = dict(contexts[0].get("values", {}))
                temp_context["values"][src_name] = full
                return _run_update_kv(temp_context, argument_names, attrs)

            def _run_paged_attention_multi(contexts, argument_names, launch_meta):
                attrs = (launch_meta or {}).get("op_attrs", {})
                q_name = argument_names[0]
                out_name = argument_names[4]
                q_desc = _find_launch_buffer_desc(contexts[0], q_name, launch_meta, 0)
                out_desc = _find_launch_buffer_desc(contexts[0], out_name, launch_meta, 4)
                if q_desc is None or out_desc is None:
                    return [_run_paged_attention(context, argument_names, attrs) for context in contexts]
                full_q = _materialize_global_tensor(contexts, q_name, q_desc, _desc_distributed_type(q_desc))
                temp_context = dict(contexts[0])
                temp_context["values"] = dict(contexts[0].get("values", {}))
                temp_context["values"][q_name] = full_q
                temp_out = _empty_like_global(out_desc, _resolve_shape(contexts[0], out_desc), full_q.device, _desc_distributed_type(out_desc))
                temp_context["values"][out_name] = temp_out
                _run_paged_attention(temp_context, argument_names, attrs)
                return _write_distributed_tensor(contexts, out_name, temp_context["values"][out_name], out_desc, _desc_distributed_type(out_desc))

            def _parallel_pe_enabled():
                value = os.environ.get("NNCASE_CUDA_PARALLEL_PE", "1")
                return str(value).strip().lower() not in ("0", "false", "no", "off")

            def _parallel_pe_min_count():
                value = os.environ.get("NNCASE_CUDA_PARALLEL_PE_MIN", "2")
                try:
                    return max(1, int(value))
                except ValueError:
                    return 2

            def _ensure_pe_streams(contexts):
                if not _parallel_pe_enabled() or len(contexts) < _parallel_pe_min_count():
                    return
                torch = _require_torch()
                if not torch.cuda.is_available():
                    return
                global _PE_STREAMS
                while len(_PE_STREAMS) < len(contexts):
                    _PE_STREAMS.append(torch.cuda.Stream(device=torch.cuda.current_device()))
                for context, stream in zip(contexts, _PE_STREAMS):
                    context["torch_stream"] = stream

            def _synchronize_pe_streams(contexts):
                torch = _TORCH
                if torch is None or not torch.cuda.is_available():
                    return
                streams = []
                for context in contexts:
                    stream = context.get("torch_stream")
                    if stream is not None and all(stream is not existing for existing in streams):
                        streams.append(stream)
                for stream in streams:
                    stream.synchronize()

            def _synchronize_cuda_device():
                torch = _TORCH
                if torch is not None and torch.cuda.is_available():
                    torch.cuda.synchronize()

            def _run_pe_launch_on_context(kind, op_name, context, argument_names, launch_meta):
                stream = context.get("torch_stream")
                torch = _TORCH
                if stream is not None and torch is not None and torch.cuda.is_available():
                    with torch.cuda.stream(stream):
                        return _execute_launch(kind, op_name, context, argument_names, bool(launch_meta.get("requires_collective", False)), launch_meta)
                return _execute_launch(kind, op_name, context, argument_names, bool(launch_meta.get("requires_collective", False)), launch_meta)

            def _run_pe_local_launches(contexts, kind, op_name, argument_names, launch_meta):
                _ensure_pe_streams(contexts)
                if not _parallel_pe_enabled() or len(contexts) < _parallel_pe_min_count() or not any(context.get("torch_stream") is not None for context in contexts):
                    return [
                        _execute_launch(kind, op_name, context, argument_names, bool(launch_meta.get("requires_collective", False)), launch_meta)
                        for context in contexts
                    ]
                result = [
                    _run_pe_launch_on_context(kind, op_name, context, argument_names, launch_meta)
                    for context in contexts
                ]
                _synchronize_pe_streams(contexts)
                return result

            def _multi_pe_contexts(function_id, function_args, stream, all_data_pools, all_output_pools, all_rdata_pools, all_block_local_rdata_pools, ccl_scratch_pool=0, ccl_scratch_bytes=0):
                function_meta = _get_function_metadata(function_id)
                pe_count = len(all_data_pools or ())
                if pe_count == 0 or pe_count != len(all_output_pools or ()) or pe_count != len(all_rdata_pools or ()):
                    raise ValueError("multi-PE CUDA/Triton launch requires matching all_data_pools/all_output_pools/all_rdata_pools")
                if not all_block_local_rdata_pools:
                    all_block_local_rdata_pools = tuple(0 for _ in range(pe_count))
                if pe_count != len(all_block_local_rdata_pools or ()):
                    raise ValueError("multi-PE CUDA/Triton launch requires matching all_block_local_rdata_pools")
                contexts = []
                for pe in range(pe_count):
                    context = _make_context(
                        pe,
                        int(all_data_pools[pe]),
                        int(all_output_pools[pe]),
                        int(all_rdata_pools[pe]),
                        function_args,
                        stream,
                        function_meta,
                        all_data_pools,
                        all_output_pools,
                        all_rdata_pools,
                        int(all_block_local_rdata_pools[pe]),
                        all_block_local_rdata_pools,
                        ccl_scratch_pool,
                        ccl_scratch_bytes)
                    _bind_function_args(context, function_meta.get("parameters", []), function_args)
                    contexts.append(context)
                return function_meta, contexts

            def _selected_multi_pe_launches(function_meta, contexts):
                ordered = sorted(function_meta.get("launches", []), key=lambda launch: int(launch.get("ordinal", 0)))
                is_shape_bucket_entry = (
                    function_meta.get("is_entry")
                    and len(ordered) > 1
                    and all(launch.get("kind") == "function" and str(launch.get("op_name", "")).startswith("main_segment_") for launch in ordered)
                )
                if not is_shape_bucket_entry:
                    return ordered
                selected = _select_shape_bucket_launch(
                    function_meta,
                    [int(launch.get("ordinal", 0)) for launch in ordered],
                    int(_symbol_env(contexts[0]).get("sequence_length", 0)))
                return [launch for launch in ordered if int(launch.get("ordinal", 0)) == selected]

            def _function_parent_descs(contexts, launch_meta, callee_meta):
                argument_names = list(launch_meta.get("arguments", []))
                filtered = _filter_function_argument_items(argument_names)
                parameters = list(callee_meta.get("parameters", []))
                if len(filtered) != len(parameters):
                    return None
                parameter_descs = {
                    desc.get("name"): desc
                    for desc in callee_meta.get("parameter_descriptors", [])
                    if desc.get("name") is not None
                }
                descs = {}
                for param_index, param_name in enumerate(parameters):
                    arg_index, arg_name = filtered[param_index]
                    desc = _find_launch_buffer_desc(contexts[0], arg_name, launch_meta, arg_index)
                    if desc is None:
                        param_desc = parameter_descs.get(param_name, {})
                        if str(param_desc.get("type", "")).startswith("&"):
                            descs[param_name] = None
                            continue
                        return None
                    descs[param_name] = desc
                return descs

            def _strip_l0_name(name):
                return str(name)[:-3] if isinstance(name, str) and str(name).endswith("_L0") else str(name)

            def _is_attention_softmax(launch):
                return (launch or {}).get("op_name") in ("softmax", "vectorized_softmax")

            def _attention_parse_scalar(name):
                try:
                    return float(str(name))
                except (TypeError, ValueError):
                    return None

            def _try_match_attention_compute_pattern(launches, parent_descs, callee_buffers):
                matmuls = [launch for launch in launches if launch.get("op_name") == "matmul"]
                softmaxes = [launch for launch in launches if _is_attention_softmax(launch)]
                if len(matmuls) != 2 or len(softmaxes) != 1:
                    return None
                allowed_ops = {"memcopy", "matmul", "elementwise.mul", "elementwise.add", "softmax", "vectorized_softmax"}
                if any(launch.get("op_name") not in allowed_ops for launch in launches):
                    return None
                ordered_matmuls = sorted(matmuls, key=lambda launch: int(launch.get("ordinal", 0)))
                qk_launch, av_launch = ordered_matmuls
                softmax_launch = softmaxes[0]
                if not (int(qk_launch.get("ordinal", 0)) < int(softmax_launch.get("ordinal", 0)) < int(av_launch.get("ordinal", 0))):
                    return None
                qk_attrs = (qk_launch or {}).get("op_attrs", {})
                av_attrs = (av_launch or {}).get("op_attrs", {})
                if qk_attrs.get("transpose_a") or not bool(qk_attrs.get("transpose_b", False)):
                    return None
                if av_attrs.get("transpose_a") or av_attrs.get("transpose_b"):
                    return None
                qk_args = list(qk_launch.get("arguments", []))
                softmax_args = list(softmax_launch.get("arguments", []))
                av_args = list(av_launch.get("arguments", []))
                if len(qk_args) < 3 or len(softmax_args) < 2 or len(av_args) < 3:
                    return None
                q_name = _strip_l0_name(qk_args[0])
                k_name = _strip_l0_name(qk_args[1])
                scores_name = _strip_l0_name(qk_args[2])
                current_name = scores_name
                scale = 1.0
                mask_name = None
                between = [
                    launch for launch in launches
                    if int(qk_launch.get("ordinal", 0)) < int(launch.get("ordinal", 0)) < int(softmax_launch.get("ordinal", 0))
                    and launch.get("op_name") != "memcopy"
                ]
                for launch in sorted(between, key=lambda item: int(item.get("ordinal", 0))):
                    op_name = launch.get("op_name")
                    args = [_strip_l0_name(arg) for arg in list(launch.get("arguments", []))]
                    if op_name == "elementwise.mul" and len(args) >= 3:
                        lhs, rhs, out = args[0], args[1], args[2]
                        if lhs == current_name:
                            scalar = _attention_parse_scalar(rhs)
                        elif rhs == current_name:
                            scalar = _attention_parse_scalar(lhs)
                        else:
                            return None
                        if scalar is None:
                            return None
                        scale *= scalar
                        current_name = out
                        continue
                    if op_name == "elementwise.add" and len(args) >= 3:
                        lhs, rhs, out = args[0], args[1], args[2]
                        if lhs == current_name:
                            candidate_mask = rhs
                        elif rhs == current_name:
                            candidate_mask = lhs
                        else:
                            return None
                        if candidate_mask not in parent_descs:
                            return None
                        mask_name = candidate_mask
                        current_name = out
                        continue
                    return None
                softmax_input = _strip_l0_name(softmax_args[0])
                probs_name = _strip_l0_name(softmax_args[1])
                if softmax_input != current_name:
                    return None
                after_softmax = [
                    launch for launch in launches
                    if int(softmax_launch.get("ordinal", 0)) < int(launch.get("ordinal", 0)) < int(av_launch.get("ordinal", 0))
                    and launch.get("op_name") != "memcopy"
                ]
                if after_softmax:
                    return None
                if _strip_l0_name(av_args[0]) != probs_name:
                    return None
                v_name = _strip_l0_name(av_args[1])
                out_name = _strip_l0_name(av_args[2])
                required = (q_name, k_name, v_name, out_name)
                if not all(name in parent_descs for name in required):
                    return None
                softmax_attrs = (softmax_launch or {}).get("op_attrs", {})
                axis = int(softmax_attrs.get("axis", -1))
                if axis not in (-1, 2, 3):
                    return None
                mask_desc = parent_descs.get(mask_name) if mask_name is not None else None
                return {
                    "q": parent_descs[q_name],
                    "k": parent_descs[k_name],
                    "v": parent_descs[v_name],
                    "out": parent_descs[out_name],
                    "mask": mask_desc,
                    "attrs": {
                        "scale": scale,
                        "causal": bool(qk_attrs.get("causal", qk_attrs.get("is_causal", False))),
                    },
                }

            def _is_structural_function_launch(contexts, launch_meta):
                op_name = str((launch_meta or {}).get("op_name", ""))
                if op_name.startswith("main_segment_"):
                    return True
                if not contexts:
                    return False
                function_id = contexts[0]["module_metadata"].get("function_ids", {}).get(op_name)
                if function_id is None:
                    return False
                callee_meta = _get_function_metadata(function_id)
                return bool(callee_meta.get("is_entry"))

            def _try_execute_native_function_launch(contexts, launch_meta):
                allow_compute_fusion = _fused_kernel_allows_compute_fusion()
                allow_ccl_fusion = _fused_kernel_allows_ccl_fusion()
                op_name = launch_meta.get("op_name")
                function_id = contexts[0]["module_metadata"].get("function_ids", {}).get(op_name)
                if function_id is None:
                    return _TRITON_NATIVE_UNSUPPORTED
                callee_meta = _get_function_metadata(function_id)
                parent_descs = _function_parent_descs(contexts, launch_meta, callee_meta)
                if parent_descs is None:
                    return _TRITON_NATIVE_UNSUPPORTED
                launches = sorted(callee_meta.get("launches", []), key=lambda launch: int(launch.get("ordinal", 0)))
                ccl_ops = ("tensor_load", "tensor_store", "gather_reduce_scatter")
                has_ccl_launch = any(launch.get("kind") == "collective" or launch.get("op_name") in ccl_ops for launch in launches)
                if has_ccl_launch and not allow_ccl_fusion:
                    return _triton_native_unsupported(f"fused function contains CCL launches but fused-kernel={_fused_kernel_mode()} does not enable CCL fusion")
                matmuls = [launch for launch in launches if launch.get("op_name") == "matmul"]
                swishes = [launch for launch in launches if launch.get("op_name") == "swish"]
                multiplies = [launch for launch in launches if launch.get("op_name") == "elementwise.mul"]
                adds = [launch for launch in launches if launch.get("op_name") == "elementwise.add"]
                wheres = [launch for launch in launches if launch.get("op_name") == "elementwise.where"]
                layer_norms = [launch for launch in launches if launch.get("op_name") == "vectorized_layer_norm"]
                transposes = [launch for launch in launches if launch.get("op_name") == "transpose"]
                casts = [launch for launch in launches if launch.get("op_name") == "elementwise.cast"]
                callee_buffers = callee_meta.get("buffers", {})

                def _callee_buffer_desc(name):
                    key = str(name)
                    return callee_buffers.get(key) or callee_buffers.get(f"{key}_L0")

                if allow_compute_fusion:
                    attention_match = _try_match_attention_compute_pattern(launches, parent_descs, callee_buffers)
                    if attention_match is not None:
                        return _run_pe_flash_attention_desc_triton(contexts, attention_match["q"], attention_match["k"], attention_match["v"], attention_match["out"], attention_match["attrs"], attention_match.get("mask"))

                if (
                    len(adds) == 1
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "elementwise.add") for launch in launches)
                ):
                    add_args = list(adds[0].get("arguments", []))
                    if len(add_args) >= 3:
                        lhs_name = _strip_l0_name(add_args[0])
                        rhs_name = _strip_l0_name(add_args[1])
                        out_name = _strip_l0_name(add_args[2])
                        if lhs_name in parent_descs and rhs_name in parent_descs and out_name in parent_descs:
                            return _run_pe_binary_desc_triton(
                                contexts,
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                parent_descs[out_name],
                                0)

                compares = [launch for launch in launches if launch.get("op_name") == "elementwise.compare.equal"]
                if (
                    len(compares) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "elementwise.compare.equal") for launch in launches)
                ):
                    cmp_args = list(compares[0].get("arguments", []))
                    if len(cmp_args) >= 3:
                        lhs_name = _strip_l0_name(cmp_args[0])
                        rhs_name = _strip_l0_name(cmp_args[1])
                        out_name = _strip_l0_name(cmp_args[2])
                        if lhs_name in parent_descs and rhs_name in parent_descs and out_name in parent_descs:
                            return _run_pe_binary_desc_triton(
                                contexts,
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                parent_descs[out_name],
                                2)

                sins = [launch for launch in launches if launch.get("op_name") == "elementwise.sin"]
                if (
                    len(sins) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "elementwise.sin") for launch in launches)
                ):
                    sin_args = list(sins[0].get("arguments", []))
                    if len(sin_args) >= 2:
                        input_name = _strip_l0_name(sin_args[0])
                        out_name = _strip_l0_name(sin_args[1])
                        if input_name in parent_descs and out_name in parent_descs:
                            return _run_pe_unary_desc_triton(
                                contexts,
                                parent_descs[input_name],
                                parent_descs[out_name],
                                2)

                position_ids = [launch for launch in launches if launch.get("op_name") == "get_position_ids"]
                if (
                    len(position_ids) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "get_position_ids") for launch in launches)
                ):
                    pos_args = list(position_ids[0].get("arguments", []))
                    if len(pos_args) >= 2:
                        out_name = _strip_l0_name(pos_args[1])
                        if out_name in parent_descs:
                            return _run_pe_position_ids_desc_triton(contexts, parent_descs[out_name])

                if len(casts) == 1 and not transposes and all(launch.get("op_name") in ("memcopy", "elementwise.cast") for launch in launches):
                    parameters = list(callee_meta.get("parameters", []))
                    if len(parameters) >= 2 and parameters[0] in parent_descs and parameters[-1] in parent_descs:
                        return _run_pe_copy_desc_triton(
                            contexts,
                            parent_descs[parameters[0]],
                            parent_descs[parameters[-1]])

                if len(transposes) == 1 and all(launch.get("op_name") in ("memcopy", "elementwise.cast", "transpose") for launch in launches):
                    parameters = list(callee_meta.get("parameters", []))
                    if len(parameters) >= 2 and parameters[0] in parent_descs and parameters[-1] in parent_descs:
                        return _run_pe_transpose_desc_triton(
                            contexts,
                            parent_descs[parameters[0]],
                            parent_descs[parameters[-1]],
                            (transposes[0] or {}).get("op_attrs", {}))

                if (
                    len(wheres) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not transposes
                    and all(launch.get("op_name") in ("memcopy", "elementwise.where") for launch in launches)
                ):
                    where_args = list(wheres[0].get("arguments", []))
                    if len(where_args) >= 4:
                        cond_name = _strip_l0_name(where_args[0])
                        lhs_name = _strip_l0_name(where_args[1])
                        rhs_name = _strip_l0_name(where_args[2])
                        out_name = _strip_l0_name(where_args[3])
                        required = (cond_name, lhs_name, rhs_name, out_name)
                        if all(name in parent_descs for name in required):
                            return _run_pe_where_desc_triton(
                                contexts,
                                parent_descs[cond_name],
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                parent_descs[out_name])

                if (
                    len(layer_norms) == 1
                    and not adds
                    and not wheres
                    and not matmuls
                    and not transposes
                    and all(launch.get("op_name") in ("memcopy", "vectorized_layer_norm") for launch in launches)
                ):
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    if len(layer_norm_args) >= 5:
                        input_name = _strip_l0_name(layer_norm_args[0])
                        scale_name = _strip_l0_name(layer_norm_args[1])
                        bias_name = _strip_l0_name(layer_norm_args[2])
                        out_name = _strip_l0_name(layer_norm_args[4])
                        required = (input_name, scale_name, bias_name, out_name)
                        if all(name in parent_descs for name in required):
                            return _run_pe_layer_norm_desc_triton(
                                contexts,
                                parent_descs[input_name],
                                parent_descs[scale_name],
                                parent_descs[bias_name],
                                parent_descs[out_name],
                                (layer_norms[0] or {}).get("op_attrs", {}))

                if (
                    len(layer_norms) == 1
                    and len(transposes) == 1
                    and len(casts) == 1
                    and not adds
                    and not wheres
                    and not matmuls
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "vectorized_layer_norm", "transpose", "elementwise.cast") for launch in launches)
                ):
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    cast_args = list(casts[0].get("arguments", []))
                    if len(layer_norm_args) >= 5 and len(cast_args) >= 2:
                        input_name = _strip_l0_name(layer_norm_args[0])
                        scale_name = _strip_l0_name(layer_norm_args[1])
                        bias_name = _strip_l0_name(layer_norm_args[2])
                        layer_norm_out = _strip_l0_name(layer_norm_args[4])
                        transpose_args = list(transposes[0].get("arguments", []))
                        transpose_out = _strip_l0_name(transpose_args[1]) if len(transpose_args) >= 2 else None
                        cast_in = _strip_l0_name(cast_args[0])
                        out_name = _strip_l0_name(cast_args[1])
                        required = (input_name, scale_name, bias_name, out_name)
                        if all(name in parent_descs for name in required):
                            fused_result = _run_pe_layer_norm_transpose_desc_triton(
                                contexts,
                                parent_descs[input_name],
                                parent_descs[scale_name],
                                parent_descs[bias_name],
                                parent_descs[out_name],
                                (layer_norms[0] or {}).get("op_attrs", {}),
                                (transposes[0] or {}).get("op_attrs", {}))
                            if fused_result is not _TRITON_NATIVE_UNSUPPORTED:
                                return fused_result
                            layer_norm_out_desc = parent_descs.get(layer_norm_out) or _callee_buffer_desc(layer_norm_out)
                            transpose_out_desc = parent_descs.get(transpose_out) or _callee_buffer_desc(transpose_out)
                            if layer_norm_out_desc is not None and transpose_out_desc is not None and transpose_out == cast_in:
                                result = _run_pe_layer_norm_desc_triton(
                                    contexts,
                                    parent_descs[input_name],
                                    parent_descs[scale_name],
                                    parent_descs[bias_name],
                                    layer_norm_out_desc,
                                    (layer_norms[0] or {}).get("op_attrs", {}))
                                if result is _TRITON_NATIVE_UNSUPPORTED:
                                    return result
                                result = _run_pe_transpose_desc_triton(
                                    contexts,
                                    layer_norm_out_desc,
                                    transpose_out_desc,
                                    (transposes[0] or {}).get("op_attrs", {}))
                                if result is _TRITON_NATIVE_UNSUPPORTED:
                                    return result
                                return _run_pe_copy_desc_triton(
                                    contexts,
                                    transpose_out_desc,
                                    parent_descs[out_name])
                            return fused_result

                if (
                    len(adds) == 1
                    and len(layer_norms) == 1
                    and not wheres
                    and not matmuls
                    and not transposes
                    and all(launch.get("op_name") in ("memcopy", "elementwise.add", "vectorized_layer_norm") for launch in launches)
                ):
                    add_args = list(adds[0].get("arguments", []))
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    if len(add_args) >= 3 and len(layer_norm_args) >= 5:
                        add_lhs = _strip_l0_name(add_args[0])
                        add_rhs = _strip_l0_name(add_args[1])
                        add_out = _strip_l0_name(add_args[2])
                        layer_norm_input = _strip_l0_name(layer_norm_args[0])
                        scale_name = _strip_l0_name(layer_norm_args[1])
                        bias_name = _strip_l0_name(layer_norm_args[2])
                        out_name = _strip_l0_name(layer_norm_args[4])
                        add_out_desc = parent_descs.get(add_out) or _callee_buffer_desc(add_out)
                        required = (add_lhs, add_rhs, scale_name, bias_name, out_name)
                        if add_out == layer_norm_input and add_out_desc is not None and all(name in parent_descs for name in required):
                            result = _run_pe_binary_desc_triton(
                                contexts,
                                parent_descs[add_lhs],
                                parent_descs[add_rhs],
                                add_out_desc,
                                0)
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            return _run_pe_layer_norm_desc_triton(
                                contexts,
                                add_out_desc,
                                parent_descs[scale_name],
                                parent_descs[bias_name],
                                parent_descs[out_name],
                                (layer_norms[0] or {}).get("op_attrs", {}))

                if (
                    len(layer_norms) == 1
                    and len(matmuls) == 1
                    and not adds
                    and not wheres
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "vectorized_layer_norm", "matmul") for launch in launches)
                ):
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    matmul_args = list(matmuls[0].get("arguments", []))
                    if len(layer_norm_args) >= 5 and len(matmul_args) >= 3:
                        input_name = _strip_l0_name(layer_norm_args[0])
                        scale_name = _strip_l0_name(layer_norm_args[1])
                        bias_name = _strip_l0_name(layer_norm_args[2])
                        layer_norm_out = _strip_l0_name(layer_norm_args[4])
                        matmul_lhs = _strip_l0_name(matmul_args[0])
                        matmul_rhs = _strip_l0_name(matmul_args[1])
                        matmul_out = _strip_l0_name(matmul_args[2])
                        layer_norm_out_desc = parent_descs.get(layer_norm_out) or _callee_buffer_desc(layer_norm_out)
                        required = (input_name, scale_name, bias_name, matmul_rhs, matmul_out)
                        if layer_norm_out == matmul_lhs and layer_norm_out_desc is not None and all(name in parent_descs for name in required):
                            result = _run_pe_layer_norm_desc_triton(
                                contexts,
                                parent_descs[input_name],
                                parent_descs[scale_name],
                                parent_descs[bias_name],
                                layer_norm_out_desc,
                                (layer_norms[0] or {}).get("op_attrs", {}))
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            return _run_pe_matmul_desc_triton(
                                contexts,
                                layer_norm_out_desc,
                                parent_descs[matmul_rhs],
                                parent_descs[matmul_out],
                                (matmuls[0] or {}).get("op_attrs", {}))

                if (
                    len(adds) == 1
                    and len(layer_norms) == 1
                    and len(matmuls) == 1
                    and not wheres
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "elementwise.add", "vectorized_layer_norm", "matmul") for launch in launches)
                ):
                    add_args = list(adds[0].get("arguments", []))
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    matmul_args = list(matmuls[0].get("arguments", []))
                    if len(add_args) >= 3 and len(layer_norm_args) >= 5 and len(matmul_args) >= 3:
                        add_lhs = _strip_l0_name(add_args[0])
                        add_rhs = _strip_l0_name(add_args[1])
                        add_out = _strip_l0_name(add_args[2])
                        layer_norm_input = _strip_l0_name(layer_norm_args[0])
                        layer_norm_scale = _strip_l0_name(layer_norm_args[1])
                        layer_norm_bias = _strip_l0_name(layer_norm_args[2])
                        layer_norm_out = _strip_l0_name(layer_norm_args[4])
                        matmul_lhs = _strip_l0_name(matmul_args[0])
                        matmul_rhs = _strip_l0_name(matmul_args[1])
                        matmul_out = _strip_l0_name(matmul_args[2])
                        required = (
                            add_lhs,
                            add_rhs,
                            layer_norm_scale,
                            layer_norm_bias,
                            matmul_rhs,
                            matmul_out,
                        )
                        add_out_desc = parent_descs.get(add_out) or _callee_buffer_desc(add_out)
                        layer_norm_out_desc = parent_descs.get(layer_norm_out) or _callee_buffer_desc(layer_norm_out)
                        if (
                            add_out == layer_norm_input
                            and layer_norm_out == matmul_lhs
                            and add_out_desc is not None
                            and layer_norm_out_desc is not None
                            and all(name in parent_descs for name in required)
                        ):
                            result = _run_pe_binary_desc_triton(
                                contexts,
                                parent_descs[add_lhs],
                                parent_descs[add_rhs],
                                add_out_desc,
                                0)
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            result = _run_pe_layer_norm_desc_triton(
                                contexts,
                                add_out_desc,
                                parent_descs[layer_norm_scale],
                                parent_descs[layer_norm_bias],
                                layer_norm_out_desc,
                                (layer_norms[0] or {}).get("op_attrs", {}))
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            return _run_pe_matmul_desc_triton(
                                contexts,
                                layer_norm_out_desc,
                                parent_descs[matmul_rhs],
                                parent_descs[matmul_out],
                                (matmuls[0] or {}).get("op_attrs", {}))

                coses = [launch for launch in launches if launch.get("op_name") == "elementwise.cos"]
                if (
                    len(multiplies) == 1
                    and len(coses) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and not swishes
                    and all(launch.get("op_name") in ("memcopy", "elementwise.mul", "elementwise.cos") for launch in launches)
                ):
                    mul_args = list(multiplies[0].get("arguments", []))
                    cos_args = list(coses[0].get("arguments", []))
                    if len(mul_args) >= 3 and len(cos_args) >= 2:
                        lhs_name = _strip_l0_name(mul_args[0])
                        rhs_name = _strip_l0_name(mul_args[1])
                        mul_out = _strip_l0_name(mul_args[2])
                        cos_in = _strip_l0_name(cos_args[0])
                        cos_out = _strip_l0_name(cos_args[1])
                        mul_out_desc = parent_descs.get(mul_out) or _callee_buffer_desc(mul_out)
                        required = (lhs_name, rhs_name, cos_out)
                        if mul_out == cos_in and mul_out_desc is not None and all(name in parent_descs for name in required):
                            result = _run_pe_binary_desc_triton(
                                contexts,
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                mul_out_desc,
                                1)
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            return _run_pe_unary_desc_triton(
                                contexts,
                                mul_out_desc,
                                parent_descs[cos_out],
                                1)

                if (
                    len(swishes) == 1
                    and len(multiplies) == 1
                    and not adds
                    and not layer_norms
                    and not matmuls
                    and not wheres
                    and not transposes
                    and all(launch.get("op_name") in ("memcopy", "swish", "elementwise.mul") for launch in launches)
                ):
                    swish_args = list(swishes[0].get("arguments", []))
                    mul_args = list(multiplies[0].get("arguments", []))
                    if len(swish_args) >= 2 and len(mul_args) >= 3:
                        gate_name = _strip_l0_name(swish_args[0])
                        swish_out = _strip_l0_name(swish_args[1])
                        mul_inputs = [_strip_l0_name(mul_args[0]), _strip_l0_name(mul_args[1])]
                        up_candidates = [name for name in mul_inputs if name != swish_out]
                        out_name = _strip_l0_name(mul_args[2])
                        if len(up_candidates) == 1:
                            up_name = up_candidates[0]
                            swish_out_desc = parent_descs.get(swish_out) or _callee_buffer_desc(swish_out)
                            required = (gate_name, up_name, out_name)
                            if all(name in parent_descs for name in required):
                                fused_result = _run_pe_swish_mul_desc_triton(
                                    contexts,
                                    parent_descs[gate_name],
                                    parent_descs[up_name],
                                    parent_descs[out_name],
                                    (swishes[0] or {}).get("op_attrs", {}).get("beta", 1.0))
                                if fused_result is not _TRITON_NATIVE_UNSUPPORTED:
                                    return fused_result
                                if swish_out_desc is not None:
                                    result = _run_pe_unary_desc_triton(
                                        contexts,
                                        parent_descs[gate_name],
                                        swish_out_desc,
                                        3,
                                        (swishes[0] or {}).get("op_attrs", {}).get("beta", 1.0))
                                    if result is not _TRITON_NATIVE_UNSUPPORTED:
                                        result = _run_pe_binary_desc_triton(
                                            contexts,
                                            swish_out_desc,
                                            parent_descs[up_name],
                                            parent_descs[out_name],
                                            1)
                                        if result is not _TRITON_NATIVE_UNSUPPORTED:
                                            return result
                                return fused_result

                if (
                    len(wheres) == 1
                    and len(layer_norms) == 1
                    and len(matmuls) == 1
                    and not adds
                    and not swishes
                    and not multiplies
                    and all(launch.get("op_name") in ("memcopy", "elementwise.where", "vectorized_layer_norm", "matmul") for launch in launches)
                ):
                    where_args = list(wheres[0].get("arguments", []))
                    layer_norm_args = list(layer_norms[0].get("arguments", []))
                    matmul_args = list(matmuls[0].get("arguments", []))
                    if len(where_args) >= 4 and len(layer_norm_args) >= 5 and len(matmul_args) >= 3:
                        cond_name = _strip_l0_name(where_args[0])
                        lhs_name = _strip_l0_name(where_args[1])
                        rhs_name = _strip_l0_name(where_args[2])
                        where_out = _strip_l0_name(where_args[3])
                        layer_norm_input = _strip_l0_name(layer_norm_args[0])
                        scale_name = _strip_l0_name(layer_norm_args[1])
                        bias_name = _strip_l0_name(layer_norm_args[2])
                        layer_norm_out = _strip_l0_name(layer_norm_args[4])
                        matmul_lhs = _strip_l0_name(matmul_args[0])
                        matmul_rhs = _strip_l0_name(matmul_args[1])
                        matmul_out = _strip_l0_name(matmul_args[2])
                        required = (
                            cond_name,
                            lhs_name,
                            rhs_name,
                            scale_name,
                            bias_name,
                            matmul_rhs,
                            matmul_out,
                        )
                        where_out_desc = parent_descs.get(where_out) or _callee_buffer_desc(where_out)
                        layer_norm_out_desc = parent_descs.get(layer_norm_out) or _callee_buffer_desc(layer_norm_out)
                        if (
                            where_out == layer_norm_input
                            and layer_norm_out == matmul_lhs
                            and where_out_desc is not None
                            and layer_norm_out_desc is not None
                            and all(name in parent_descs for name in required)
                        ):
                            result = _run_pe_where_desc_triton(
                                contexts,
                                parent_descs[cond_name],
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                where_out_desc)
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            result = _run_pe_layer_norm_desc_triton(
                                contexts,
                                where_out_desc,
                                parent_descs[scale_name],
                                parent_descs[bias_name],
                                layer_norm_out_desc,
                                (layer_norms[0] or {}).get("op_attrs", {}))
                            if result is _TRITON_NATIVE_UNSUPPORTED:
                                return result
                            return _run_pe_matmul_desc_triton(
                                contexts,
                                layer_norm_out_desc,
                                parent_descs[matmul_rhs],
                                parent_descs[matmul_out],
                                (matmuls[0] or {}).get("op_attrs", {}))

                if len(matmuls) == 1 and not swishes and not multiplies and all(launch.get("op_name") in ("memcopy", "matmul") for launch in launches):
                    matmul_args = list(matmuls[0].get("arguments", []))
                    if len(matmul_args) >= 3:
                        lhs_name = _strip_l0_name(matmul_args[0])
                        rhs_name = _strip_l0_name(matmul_args[1])
                        out_name = _strip_l0_name(matmul_args[2])
                        if lhs_name in parent_descs and rhs_name in parent_descs and out_name in parent_descs:
                            return _run_pe_matmul_desc_triton(
                                contexts,
                                parent_descs[lhs_name],
                                parent_descs[rhs_name],
                                parent_descs[out_name],
                                (matmuls[0] or {}).get("op_attrs", {}))

                if allow_compute_fusion and len(matmuls) == 2 and len(multiplies) == 1 and not swishes and not adds and not layer_norms and not wheres and not transposes:
                    ordered_matmuls = sorted(matmuls, key=lambda launch: int(launch.get("ordinal", 0)))
                    first_matmul_args = list(ordered_matmuls[0].get("arguments", []))
                    second_matmul_args = list(ordered_matmuls[1].get("arguments", []))
                    mul_args = list(multiplies[0].get("arguments", []))
                    if len(first_matmul_args) >= 3 and len(second_matmul_args) >= 3 and len(mul_args) >= 3:
                        lhs_name = _strip_l0_name(first_matmul_args[0])
                        up_rhs_name = _strip_l0_name(first_matmul_args[1])
                        up_name = _strip_l0_name(first_matmul_args[2])
                        mul_inputs = [_strip_l0_name(mul_args[0]), _strip_l0_name(mul_args[1])]
                        mul_out = _strip_l0_name(mul_args[2])
                        second_lhs = _strip_l0_name(second_matmul_args[0])
                        down_rhs_name = _strip_l0_name(second_matmul_args[1])
                        out_name = _strip_l0_name(second_matmul_args[2])
                        gate_candidates = [name for name in mul_inputs if name != up_name]
                        if up_name in mul_inputs and len(gate_candidates) == 1 and mul_out == second_lhs:
                            gate_name = gate_candidates[0]
                            required = (gate_name, lhs_name, up_rhs_name, down_rhs_name, out_name)
                            if all(name in parent_descs for name in required):
                                result = _run_pe_matmul_mul_matmul_desc_triton(
                                    contexts,
                                    parent_descs[gate_name],
                                    parent_descs[lhs_name],
                                    parent_descs[up_rhs_name],
                                    parent_descs[down_rhs_name],
                                    parent_descs[out_name])
                                if result is not _TRITON_NATIVE_UNSUPPORTED:
                                    return result

                if allow_compute_fusion and len(matmuls) == 1 and len(swishes) == 1 and len(multiplies) == 1:
                    swish_args = list(swishes[0].get("arguments", []))
                    mul_args = list(multiplies[0].get("arguments", []))
                    matmul_args = list(matmuls[0].get("arguments", []))
                    if len(swish_args) >= 2 and len(mul_args) >= 3 and len(matmul_args) >= 3:
                        gate_name = _strip_l0_name(swish_args[0])
                        swish_out = _strip_l0_name(swish_args[1])
                        mul_inputs = [_strip_l0_name(mul_args[0]), _strip_l0_name(mul_args[1])]
                        matmul_lhs = _strip_l0_name(matmul_args[0])
                        matmul_rhs = _strip_l0_name(matmul_args[1])
                        matmul_out = _strip_l0_name(matmul_args[2])
                        mul_out = _strip_l0_name(mul_args[2])
                        if matmul_out in mul_inputs and swish_out in mul_inputs:
                            required = (gate_name, matmul_lhs, matmul_rhs, mul_out)
                            if all(name in parent_descs for name in required):
                                result = _run_pe_matmul_swish_mul_desc_triton(
                                    contexts,
                                    parent_descs[gate_name],
                                    parent_descs[matmul_lhs],
                                    parent_descs[matmul_rhs],
                                    parent_descs[mul_out],
                                    (swishes[0] or {}).get("op_attrs", {}).get("beta", 1.0))
                                if result is not _TRITON_NATIVE_UNSUPPORTED:
                                    return result
                        up_candidates = [name for name in mul_inputs if name != swish_out]
                        weight_name = _strip_l0_name(matmul_args[1])
                        out_name = _strip_l0_name(matmul_args[2])
                        if len(up_candidates) == 1:
                            up_name = up_candidates[0]
                            required = (gate_name, up_name, weight_name, out_name)
                            if all(name in parent_descs for name in required):
                                fused_result = _run_pe_silu_mul_matmul_desc_triton(
                                    contexts,
                                    parent_descs[gate_name],
                                    parent_descs[up_name],
                                    parent_descs[weight_name],
                                    parent_descs[out_name])
                                if fused_result is not _TRITON_NATIVE_UNSUPPORTED:
                                    return fused_result
                                swish_out_desc = parent_descs.get(swish_out) or _callee_buffer_desc(swish_out)
                                mul_out = _strip_l0_name(mul_args[2])
                                mul_out_desc = parent_descs.get(mul_out) or _callee_buffer_desc(mul_out)
                                if swish_out_desc is not None and mul_out_desc is not None:
                                    result = _run_pe_unary_desc_triton(
                                        contexts,
                                        parent_descs[gate_name],
                                        swish_out_desc,
                                        3,
                                        (swishes[0] or {}).get("op_attrs", {}).get("beta", 1.0))
                                    if result is not _TRITON_NATIVE_UNSUPPORTED:
                                        result = _run_pe_binary_desc_triton(
                                            contexts,
                                            swish_out_desc,
                                            parent_descs[up_name],
                                            mul_out_desc,
                                            1)
                                        if result is not _TRITON_NATIVE_UNSUPPORTED:
                                            result = _run_pe_matmul_desc_triton(
                                                contexts,
                                                mul_out_desc,
                                                parent_descs[weight_name],
                                                parent_descs[out_name],
                                                (matmuls[0] or {}).get("op_attrs", {}))
                                            if result is not _TRITON_NATIVE_UNSUPPORTED:
                                                return result
                                return fused_result

                if not allow_compute_fusion:
                    return _triton_native_unsupported(f"no structural per-op native lowering matched and fused function kernels are disabled by fused-kernel={_fused_kernel_mode()}")
                return _TRITON_NATIVE_UNSUPPORTED

            def _execute_multi_pe_nested_function(contexts, launch_meta):
                op_name = launch_meta.get("op_name")
                function_id = contexts[0]["module_metadata"].get("function_ids", {}).get(op_name)
                if function_id is None:
                    raise KeyError(f"unknown nested cuda triton function: {op_name}")
                callee_meta = _get_function_metadata(function_id)
                argument_names = list(launch_meta.get("arguments", []))
                filtered = _filter_function_argument_items(argument_names)
                filtered_names = _filter_function_argument_names(argument_names)
                expected = len(callee_meta.get("parameters", []))
                if len(filtered_names) != expected:
                    raise ValueError(f"nested function {op_name} expects {expected} filtered args, got {len(filtered_names)} from {argument_names}")
                callee_contexts = []
                for context in contexts:
                    context["current_launch_metadata"] = launch_meta
                    nested_args = tuple(_resolve_nested_argument(context, name, index, launch_meta) for index, name in filtered)
                    callee_context = _make_context(
                        context["pe_id"],
                        context["data_pool"],
                        context["output_pool"],
                        context["rdata_pool"],
                        nested_args,
                        context["stream"],
                        callee_meta,
                        context.get("all_data_pools"),
                        context.get("all_output_pools"),
                        context.get("all_rdata_pools"),
                        context.get("block_local_rdata_pool"),
                        context.get("all_block_local_rdata_pools"),
                        context.get("ccl_scratch_pool"),
                        context.get("ccl_scratch_bytes"))
                    callee_context["symbol_env"].update(_symbol_env(context))
                    _bind_function_args(callee_context, callee_meta.get("parameters", []), nested_args)
                    callee_contexts.append(callee_context)
                return _execute_multi_pe_function_contexts(callee_meta, callee_contexts)

            def _execute_multi_pe_launch_body(contexts, launch_meta):
                kind = launch_meta.get("kind")
                op_name = launch_meta.get("op_name")
                argument_names = list(launch_meta.get("arguments", []))
                if _is_elided_ccl_tail_launch(launch_meta):
                    return contexts[0] if contexts else None
                for context in contexts:
                    context["current_launch_metadata"] = launch_meta
                    context["launches"].append(launch_meta)
                _prepare_partial_state_for_outputs(contexts, launch_meta)
                if any(context.get("partial_aliases") for context in contexts):
                    _synchronize_pe_streams(contexts)
                    _materialize_partial_aliases(contexts, launch_meta)
                    _materialize_partial_inputs(contexts, launch_meta)
                if kind == "function":
                    _clear_triton_native_unsupported()
                    native = _try_execute_native_function_launch(contexts, launch_meta)
                    if native is not _TRITON_NATIVE_UNSUPPORTED:
                        _record_partial_aliases(contexts, launch_meta)
                        _run_fused_ccl_tails(contexts, launch_meta)
                        return native
                    # A device function can be a structural wrapper around PE-local
                    # cache copies and Triton-native child ops. In strict mode the
                    # child launches below still enforce native Triton coverage, so
                    # failing to match a whole-function fusion pattern is not itself
                    # a CPU/torch fallback.
                    result = _execute_multi_pe_nested_function(contexts, launch_meta)
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                _clear_triton_native_unsupported()
                native = _try_execute_triton_multi_pe_native_launch(contexts, kind, op_name, argument_names, launch_meta)
                if native is not _TRITON_NATIVE_UNSUPPORTED:
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return native
                _strict_native_triton_error(contexts, launch_meta)
                _require_native_triton_launch(kind, op_name)
                if any(context.get("partial_aliases") for context in contexts):
                    _synchronize_pe_streams(contexts)
                _materialize_partial_aliases(contexts, launch_meta)
                _materialize_partial_inputs(contexts, launch_meta)
                if op_name == "tensor_load":
                    _synchronize_pe_streams(contexts)
                    result = _run_tensor_load_multi(contexts, argument_names, launch_meta)
                    _synchronize_cuda_device()
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                if op_name == "tensor_store":
                    _synchronize_pe_streams(contexts)
                    result = _run_tensor_store_multi(contexts, argument_names, launch_meta)
                    _synchronize_cuda_device()
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                if op_name == "gather_reduce_scatter":
                    _synchronize_pe_streams(contexts)
                    result = _run_gather_reduce_scatter_multi(contexts, argument_names, launch_meta)
                    _synchronize_cuda_device()
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                if op_name in ("update_paged_attention_kvcache", "update_paged_attention_kv_cache"):
                    _synchronize_pe_streams(contexts)
                    result = _run_update_kv_multi(contexts, argument_names, launch_meta)
                    _synchronize_cuda_device()
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                if op_name == "paged_attention":
                    _synchronize_pe_streams(contexts)
                    result = _run_paged_attention_multi(contexts, argument_names, launch_meta)
                    _synchronize_cuda_device()
                    _record_partial_aliases(contexts, launch_meta)
                    _run_fused_ccl_tails(contexts, launch_meta)
                    return result
                result = _run_pe_local_launches(contexts, kind, op_name, argument_names, launch_meta)
                _record_partial_aliases(contexts, launch_meta)
                _run_fused_ccl_tails(contexts, launch_meta)
                return result

            _DEBUG_SCAN_FOUND = False

            def _debug_scan_enabled():
                value = os.environ.get("NNCASE_TRITON_SCAN_BAD", "")
                return str(value).strip().lower() in ("1", "true", "yes", "on")

            def _debug_scan_threshold():
                value = os.environ.get("NNCASE_TRITON_SCAN_ABS", "10000")
                try:
                    return float(value)
                except ValueError:
                    return 10000.0

            def _debug_scan_names(launch_meta):
                names = []
                output_indices = _launch_output_indices(launch_meta)
                for index, name in enumerate(list(launch_meta.get("arguments", []))):
                    if index not in output_indices:
                        continue
                    if isinstance(name, str) and name not in names:
                        names.append(name)
                for key, desc in (launch_meta.get("buffer_arguments", {}) or {}).items():
                    if not _is_launch_output_desc(launch_meta, key, desc):
                        continue
                    name = desc.get("name") if isinstance(desc, dict) else None
                    if isinstance(name, str) and name not in names:
                        names.append(name)
                return names

            def _debug_scan_tensor_after_launch(context, launch_meta, name, value):
                global _DEBUG_SCAN_FOUND
                if _DEBUG_SCAN_FOUND or value is None or not hasattr(value, "numel"):
                    return
                try:
                    if value.numel() == 0 or not value.is_floating_point():
                        return
                    torch = _require_torch()
                    tensor = value.detach()
                    finite = torch.isfinite(tensor)
                    finite_count = int(finite.sum().item())
                    total = int(tensor.numel())
                    finite_values = tensor[finite]
                    has_bad_finite = False
                    threshold = _debug_scan_threshold()
                    if finite_count:
                        has_bad_finite = bool((finite_values.abs() > threshold).any().item())
                    if finite_count == total and not has_bad_finite:
                        return
                    sample = tensor.flatten()[:8].detach().cpu().tolist()
                    min_value = float(finite_values.min().item()) if finite_count else float("nan")
                    max_value = float(finite_values.max().item()) if finite_count else float("nan")
                    function_name = context.get("function_metadata", {}).get("name", "?")
                    print(
                        "[nncase-triton-scan-bad] "
                        f"{function_name}:{int(launch_meta.get('ordinal', -1))} "
                        f"kind={launch_meta.get('kind')} op={launch_meta.get('op_name')} "
                        f"pe={context.get('pe_id')} name={name} shape={tuple(tensor.shape)} "
                        f"finite={finite_count}/{total} min={min_value} max={max_value} "
                        f"sample={sample}",
                        flush=True)
                    _DEBUG_SCAN_FOUND = True
                except Exception as ex:
                    print(f"[nncase-triton-scan-error] {launch_meta.get('op_name')} {name}: {ex}", flush=True)

            def _debug_scan_after_launch(contexts, launch_meta):
                if not _debug_scan_enabled():
                    return
                names = _debug_scan_names(launch_meta)
                for context in contexts:
                    values = context.get("values", {})
                    for name in names:
                        value = values.get(name)
                        desc = None
                        if value is None:
                            desc = _find_launch_buffer_desc(context, name, launch_meta)
                            if desc is not None and _distributed_is_partial(_desc_distributed_type(desc)):
                                value = _partial_fp32_tensor_for_desc(context, desc)
                            if value is None and desc is not None and desc.get("memory", {}).get("location") != "Cache":
                                try:
                                    value = _tensor_from_desc(context, desc)
                                except Exception:
                                    value = None
                        _debug_scan_tensor_after_launch(context, launch_meta, name, value)

            def _execute_multi_pe_launch(contexts, launch_meta):
                kind = launch_meta.get("kind")
                op_name = launch_meta.get("op_name")
                argument_names = list(launch_meta.get("arguments", []))
                event = _verbose_launch_begin(contexts, kind, op_name, argument_names, launch_meta)
                previous = []
                for context in contexts:
                    previous.append(context.get("_suppress_launch_verbose", False))
                    context["_suppress_launch_verbose"] = True
                try:
                    result = _execute_multi_pe_launch_body(contexts, launch_meta)
                    _debug_scan_after_launch(contexts, launch_meta)
                    return result
                finally:
                    for context, value in zip(contexts, previous):
                        if value:
                            context["_suppress_launch_verbose"] = value
                        else:
                            context.pop("_suppress_launch_verbose", None)
                    _verbose_launch_end(event)

            def _execute_multi_pe_function_contexts(function_meta, contexts):
                _persistent_tile_admission_check(contexts)
                for launch_meta in _selected_multi_pe_launches(function_meta, contexts):
                    _execute_multi_pe_launch(contexts, launch_meta)
                return contexts[0]

            def _execute_multi_pe_function(function_id, *function_args, stream=None, all_data_pools=None, all_output_pools=None, all_rdata_pools=None, all_block_local_rdata_pools=None, ccl_scratch_pool=0, ccl_scratch_bytes=0):
                function_meta, contexts = _multi_pe_contexts(function_id, function_args, stream, tuple(all_data_pools or ()), tuple(all_output_pools or ()), tuple(all_rdata_pools or ()), tuple(all_block_local_rdata_pools or ()), ccl_scratch_pool, ccl_scratch_bytes)
                _entry_begin(function_meta, function_args)
                try:
                    return _execute_multi_pe_function_contexts(function_meta, contexts)
                finally:
                    _entry_end(function_meta)

            def _transpose_to_shape(value, output):
                if value.ndim == output.ndim:
                    for perm in __import__("itertools").permutations(range(value.ndim)):
                        if tuple(value.shape[i] for i in perm) == tuple(output.shape):
                            return value.permute(*perm).contiguous()
                if value.numel() == output.numel():
                    return value.reshape(tuple(output.shape))
                return value

            def _run_matmul(context, args, attrs):
                lhs = _get_tensor(context, args[0])
                rhs = _get_tensor(context, args[1])
                try:
                    out = _get_tensor(context, args[2])
                except KeyError:
                    out = None
                if attrs.get("transpose_a"):
                    lhs = lhs.transpose(-2, -1)
                if attrs.get("transpose_b"):
                    rhs = rhs.transpose(-2, -1)
                compute_dtype = out.dtype if out is not None else lhs.dtype
                if compute_dtype is _require_torch().float32:
                    lhs = lhs.float()
                    rhs = rhs.float()
                result = lhs.matmul(rhs)
                scale = _get_tensor(context, args[4]) if len(args) > 4 else None
                if scale is not None:
                    result = result * scale
                # AutoTiling may lower matmul loadC to an unmaterialized scalar expression.
                # The CUDA PoC fallback runs one full-buffer matmul per launch, so it is not
                # a tile-loop accumulation point.
                if len(args) > 3 and args[3] == "call":
                    load_c = False
                else:
                    load_c = _get_tensor(context, args[3]) if len(args) > 3 else None
                if load_c is True:
                    if out is None:
                        out = _get_tensor(context, args[2], result)
                    result = result + out
                elif hasattr(load_c, "shape") and load_c.dtype is not _require_torch().bool:
                    result = result + load_c
                if out is None:
                    compute_dtype = result.dtype
                return _write_tensor(context, args[2], result.to(compute_dtype))

            def _run_layer_norm(context, args, attrs):
                torch = _require_torch()
                x = _get_tensor(context, args[0]).float()
                scale = _get_tensor(context, args[1]).float()
                bias = _get_tensor(context, args[2]).float()
                axis = int(attrs.get("axis", -1))
                eps = float(attrs.get("epsilon", 1e-5))
                use_mean = bool(attrs.get("use_mean", True))
                dims = tuple(range(axis if axis >= 0 else x.ndim + axis, x.ndim))
                if use_mean:
                    mean = x.mean(dim=dims, keepdim=True)
                    var = (x - mean).pow(2).mean(dim=dims, keepdim=True)
                    y = (x - mean) * torch.rsqrt(var + eps)
                else:
                    var = x.pow(2).mean(dim=dims, keepdim=True)
                    y = x * torch.rsqrt(var + eps)
                while scale.ndim < y.ndim:
                    scale = scale.unsqueeze(0)
                    bias = bias.unsqueeze(0)
                return _write_tensor(context, args[4], y * scale + bias)

            def _run_rope(context, args):
                torch = _require_torch()
                x = _get_tensor(context, args[0]).float()
                cos = _get_tensor(context, args[1]).float()
                sin = _get_tensor(context, args[2]).float()
                out = _get_tensor(context, args[3], x)
                if x.ndim == 3 and cos.ndim == 2 and int(x.shape[-1]) == int(cos.shape[-1]):
                    head, seq, dim = x.shape
                    half = dim // 2
                    cos = cos.reshape(seq, dim)
                    sin = sin.reshape(seq, dim)
                    first = x[:, :, :half]
                    second = x[:, :, half:]
                    y = torch.empty_like(x)
                    y[:, :, :half] = first * cos[:, :half].unsqueeze(0) - second * sin[:, :half].unsqueeze(0)
                    y[:, :, half:] = second * cos[:, half:].unsqueeze(0) + first * sin[:, half:].unsqueeze(0)
                else:
                    head, dim, seq = x.shape
                    half = dim // 2
                    if cos.ndim == 2 and tuple(cos.shape) == (seq, dim):
                        cos = cos.transpose(0, 1)
                        sin = sin.transpose(0, 1)
                    cos = cos.reshape(dim, seq)
                    sin = sin.reshape(dim, seq)
                    first = x[:, :half, :]
                    second = x[:, half:, :]
                    y = torch.empty_like(x)
                    y[:, :half, :] = first * cos[:half, :].unsqueeze(0) - second * sin[:half, :].unsqueeze(0)
                    y[:, half:, :] = second * cos[half:, :].unsqueeze(0) + first * sin[half:, :].unsqueeze(0)
                return _write_tensor(context, args[3], y.to(out.dtype))

            def _run_get_position_ids(context, args):
                torch = _require_torch()
                out = _get_tensor(context, args[1])
                start = int(_KV_STATE.get("current_start", 0))
                local_offset = 0
                desc = _find_launch_buffer_desc(context, args[1], context.get("current_launch_metadata"), 1)
                if desc is None:
                    bound = context.get("bound_args", {}).get(_strip_l0(args[1]))
                    if isinstance(bound, _BufferRef):
                        desc = bound.desc
                if desc is not None:
                    global_shape = _resolve_shape(context, desc)
                    _, offsets = _local_shape_and_offsets(context, desc, global_shape, _desc_distributed_type(desc))
                    shard_axes = _distributed_shard_axes(_desc_distributed_type(desc))
                    if shard_axes:
                        local_offset = int(offsets[int(shard_axes[0])])
                values = torch.arange(start + local_offset, start + local_offset + out.numel(), device=out.device, dtype=out.dtype)
                return _write_tensor(context, args[1], values.reshape(tuple(out.shape)))

            def _run_pack(context, args, attrs):
                value = _get_tensor(context, args[0])
                lanes = tuple(int(x) for x in attrs.get("lanes", []) or ())
                axes = tuple(int(x) for x in attrs.get("axes", []) or ())
                if len(lanes) != len(axes):
                    raise ValueError(f"pack lanes/axes mismatch: lanes={lanes} axes={axes}")
                result = value
                old_lanes_count = len(_vector_lanes_for_name(context, args[0]))
                for index in range(len(axes) - 1, -1, -1):
                    lane = int(lanes[index])
                    axis = int(axes[index])
                    if axis < 0:
                        continue
                    shape = list(result.shape)
                    if int(shape[axis]) % lane != 0:
                        raise ValueError(f"pack axis {axis} shape {tuple(shape)} is not divisible by lane {lane}")
                    divided_shape = shape[:axis] + [int(shape[axis]) // lane, lane] + shape[axis + 1:]
                    result = result.reshape(tuple(divided_shape))
                    rank = len(divided_shape)
                    middle_count = rank - (axis + old_lanes_count + 2)
                    perm = (
                        list(range(0, axis + 1))
                        + list(range(axis + 2, axis + 2 + max(0, middle_count)))
                        + [axis + 1]
                        + list(range(rank - old_lanes_count, rank))
                    )
                    result = result.permute(*perm).contiguous()
                    old_lanes_count += 1
                return _write_tensor(context, args[1], result)

            def _run_unpack(context, args, attrs):
                value = _get_tensor(context, args[0])
                axes = tuple(int(x) for x in attrs.get("axes", []) or ())
                result = value
                old_lanes_count = len(_vector_lanes_for_name(context, args[0]))
                if old_lanes_count == 0 and attrs.get("lanes"):
                    old_lanes_count = len(attrs.get("lanes") or [])
                for axis in axes:
                    axis = int(axis)
                    if old_lanes_count <= 0:
                        raise ValueError(f"unpack requires vector lanes for {args[0]}")
                    perm = list(range(result.ndim))
                    tail = perm[-(old_lanes_count - 1):] if old_lanes_count > 1 else []
                    perm = perm[:axis + 1] + [perm[-old_lanes_count]] + perm[axis + 1:-old_lanes_count] + tail
                    result = result.permute(*perm).contiguous()
                    shape = list(result.shape)
                    shape[axis] = int(shape[axis]) * int(shape[axis + 1])
                    del shape[axis + 1]
                    result = result.reshape(tuple(shape))
                    old_lanes_count -= 1
                return _write_tensor(context, args[1], result)

            def _merge_layout_vector_lanes(tensor, layout):
                layout = list(layout or ["Head", "Dim", "Seq"])
                logical_rank = len(layout)
                if tensor.ndim <= logical_rank:
                    return tensor
                dim_axis = layout.index("Dim") if "Dim" in layout else logical_rank - 1
                result = tensor
                while result.ndim > logical_rank:
                    lane_axis = result.ndim - 1
                    perm = list(range(result.ndim))
                    lane = perm.pop(lane_axis)
                    perm.insert(dim_axis + 1, lane)
                    result = result.permute(*perm).contiguous()
                    shape = list(result.shape)
                    shape[dim_axis] = int(shape[dim_axis]) * int(shape[dim_axis + 1])
                    del shape[dim_axis + 1]
                    result = result.reshape(tuple(shape))
                return result

            def _split_layout_vector_lanes(tensor, layout, output):
                if output is None or not hasattr(output, "shape"):
                    return tensor
                layout = list(layout or ["Head", "Dim", "Seq"])
                logical_rank = len(layout)
                target = tuple(output.shape)
                if len(target) <= logical_rank or tuple(tensor.shape) == target:
                    return tensor
                if int(tensor.numel()) != math.prod(target):
                    return tensor.reshape(target)
                dim_axis = layout.index("Dim") if "Dim" in layout else logical_rank - 1
                result = tensor
                for lane in target[logical_rank:]:
                    lane = int(lane)
                    shape = list(result.shape)
                    if int(shape[dim_axis]) % lane != 0:
                        return tensor.reshape(target)
                    divided_shape = shape[:dim_axis] + [int(shape[dim_axis]) // lane, lane] + shape[dim_axis + 1:]
                    result = result.reshape(tuple(divided_shape))
                    rank = len(divided_shape)
                    perm = list(range(0, dim_axis + 1)) + list(range(dim_axis + 2, rank)) + [dim_axis + 1]
                    result = result.permute(*perm).contiguous()
                return result.reshape(target)

            def _layout_to_hds(tensor, layout):
                layout = list(layout or ["Head", "Dim", "Seq"])
                tensor = _merge_layout_vector_lanes(tensor, layout)
                order = [layout.index("Head"), layout.index("Dim"), layout.index("Seq")]
                return tensor.permute(*order).contiguous()

            def _from_hds(tensor, layout, output=None):
                layout = list(layout or ["Head", "Dim", "Seq"])
                inverse = [0, 0, 0]
                for target_axis, name in enumerate(["Head", "Dim", "Seq"]):
                    inverse[layout.index(name)] = target_axis
                result = tensor.permute(*inverse).contiguous()
                return _split_layout_vector_lanes(result, layout, output)

            def _run_update_kv(context, args, attrs):
                torch = _require_torch()
                value = _layout_to_hds(_get_tensor(context, args[0]), attrs.get("layout")).detach()
                layer = int(attrs.get("layer_id", 0))
                kind = str(attrs.get("cache_kind", "Key")).lower()
                key = (layer, kind)
                old = _KV_STATE["cache"].get(key)
                start = int(_KV_STATE.get("current_start", 0))
                end = start + int(value.shape[2])
                if old is None:
                    old = torch.empty((value.shape[0], value.shape[1], end), dtype=value.dtype, device=value.device)
                elif int(old.shape[2]) < end:
                    grown = torch.empty((old.shape[0], old.shape[1], end), dtype=old.dtype, device=old.device)
                    grown[:, :, :old.shape[2]].copy_(old)
                    old = grown
                old[:, :, start:end].copy_(value.to(old.dtype))
                _KV_STATE["cache"][key] = old
                return None

            def _run_paged_attention(context, args, attrs):
                torch = _require_torch()
                q = _layout_to_hds(_get_tensor(context, args[0]).float(), attrs.get("layout"))
                out = _get_tensor(context, args[4], q)
                layer = int(attrs.get("layer_id", 0))
                k = _KV_STATE["cache"].get((layer, "key"))
                v = _KV_STATE["cache"].get((layer, "value"))
                if k is None or v is None:
                    raise RuntimeError(f"missing CUDA/Triton KV cache for layer {layer}")
                k = k.float()
                v = v.float()
                end = int(_KV_STATE.get("current_start", 0)) + int(q.shape[2])
                end = min(end, int(k.shape[2]), int(v.shape[2]))
                k = k[:, :, :end]
                v = v[:, :, :end]
                repeat = max(1, q.shape[0] // k.shape[0])
                k = k.repeat_interleave(repeat, dim=0)
                v = v.repeat_interleave(repeat, dim=0)
                scale_arg = _get_tensor(context, args[3])
                scale = float(scale_arg.reshape(-1)[0].item()) if hasattr(scale_arg, "shape") else float(scale_arg)
                scores = torch.einsum("hdt,hds->hts", q, k) * scale
                start = int(_KV_STATE.get("current_start", 0))
                t = q.shape[2]
                s = k.shape[2]
                query_pos = torch.arange(start, start + t, device=scores.device).view(1, t, 1)
                key_pos = torch.arange(0, s, device=scores.device).view(1, 1, s)
                scores = scores.masked_fill(key_pos > query_pos, -torch.inf)
                probs = torch.softmax(scores, dim=-1)
                y = torch.einsum("hts,hds->hdt", probs, v)
                y = _from_hds(y, attrs.get("layout"), out)
                return _write_tensor(context, args[4], y.to(out.dtype))

            def _run_gather(context, args, attrs):
                src = _get_tensor(context, args[0])
                index = _get_tensor(context, args[1]).long()
                axis = int(attrs.get("axis", 0))
                result = src.index_select(axis, index.reshape(-1))
                expected = _get_tensor(context, args[2], result)
                if result.numel() == expected.numel():
                    result = result.reshape(tuple(expected.shape))
                return _write_tensor(context, args[2], result)

            def _infer_concat_axis(inputs, output):
                out_shape = tuple(output.shape)
                for axis in range(len(out_shape)):
                    total = 0
                    matched = True
                    for tensor in inputs:
                        shape = tuple(tensor.shape)
                        if len(shape) != len(out_shape):
                            matched = False
                            break
                        total += int(shape[axis])
                        for dim, (lhs, rhs) in enumerate(zip(shape, out_shape)):
                            if dim != axis and int(lhs) != int(rhs):
                                matched = False
                                break
                        if not matched:
                            break
                    if matched and total == int(out_shape[axis]):
                        return axis
                return 0

            def _run_concat(context, args, attrs):
                torch = _require_torch()
                inputs = [_get_tensor(context, name) for name in args[:-1]]
                out = _get_tensor(context, args[-1], inputs[0] if inputs else None)
                axis = int(attrs["axis"]) if "axis" in attrs else _infer_concat_axis(inputs, out)
                result = torch.cat([tensor.to(out.dtype) for tensor in inputs], dim=axis)
                if tuple(result.shape) != tuple(out.shape) and int(result.numel()) == int(out.numel()):
                    result = result.reshape(tuple(out.shape))
                return _write_tensor(context, args[-1], result)

            def _triton_verbose_enabled():
                value = os.environ.get("NNCASE_TRITON_VERBOSE") or os.environ.get("NNCASE_TRITON_VERBOSES") or os.environ.get("NNCASE_CUDA_VERBOSE") or ""
                return str(value).strip().lower() in ("1", "true", "yes", "on", "verbose")

            def _triton_verbose_limit():
                value = os.environ.get("NNCASE_TRITON_VERBOSE_LIMIT", "0")
                try:
                    return max(0, int(value))
                except ValueError:
                    return 0

            def _verbose_contexts(context_or_contexts):
                if isinstance(context_or_contexts, (list, tuple)):
                    return list(context_or_contexts)
                return [context_or_contexts]

            def _verbose_format_shape(shape):
                if shape is None:
                    return "?"
                return "(" + ",".join(str(int(dim)) for dim in shape) + ")"

            def _verbose_format_arg(context, name, ordinal, launch_meta):
                desc = _find_launch_buffer_desc(context, name, launch_meta, ordinal)
                if desc is None:
                    bound = context.get("bound_args", {}).get(_strip_l0(name))
                    if isinstance(bound, _BufferRef):
                        desc = bound.desc
                    elif bound is not None:
                        try:
                            shape = _bound_shape(context, bound)
                            return f"{name}:shape={_verbose_format_shape(shape)}"
                        except Exception:
                            return str(name)
                if desc is None:
                    return str(name)
                try:
                    shape = _resolve_shape(context, desc)
                except Exception:
                    shape = None
                memory = desc.get("memory", {})
                dtype = desc.get("dtype", "?")
                location = memory.get("location", "?")
                distributed_type = _desc_distributed_type(desc)
                if distributed_type:
                    return f"{name}:shape={_verbose_format_shape(shape)} dtype={dtype} mem={location} dist={distributed_type}"
                return f"{name}:shape={_verbose_format_shape(shape)} dtype={dtype} mem={location}"

            def _verbose_format_attrs(attrs):
                if not attrs:
                    return "{}"
                keys = (
                    "func_name",
                    "c_source_path",
                    "layer_id",
                    "cache_kind",
                    "axis",
                    "perm",
                    "transpose_a",
                    "transpose_b",
                    "fused_reduce",
                    "in_type",
                    "out_type",
                )
                selected = {key: attrs.get(key) for key in keys if key in attrs}
                return json.dumps(selected, ensure_ascii=False, sort_keys=True)

            def _verbose_launch_begin(context_or_contexts, kind, op_name, argument_names, launch_meta):
                global _TRITON_VERBOSE_COUNT, _TRITON_VERBOSE_LIMIT_REPORTED
                if not _triton_verbose_enabled():
                    return None
                limit = _triton_verbose_limit()
                if limit > 0 and _TRITON_VERBOSE_COUNT >= limit:
                    if not _TRITON_VERBOSE_LIMIT_REPORTED:
                        print(f"[nncase-triton] verbose limit reached ({limit}); suppressing remaining launches", flush=True)
                        _TRITON_VERBOSE_LIMIT_REPORTED = True
                    return None
                _TRITON_VERBOSE_COUNT += 1
                contexts = _verbose_contexts(context_or_contexts)
                context = contexts[0] if contexts else {}
                pe_count = len(contexts) if len(contexts) > 1 else int(context.get("module_metadata", {}).get("pe_count", 1) or 1)
                function_name = context.get("function_metadata", {}).get("name", "?")
                ordinal = (launch_meta or {}).get("ordinal", "?")
                attrs = (launch_meta or {}).get("op_attrs", {})
                args = ", ".join(_verbose_format_arg(context, name, index, launch_meta or {}) for index, name in enumerate(argument_names or []))
                collective = bool((launch_meta or {}).get("requires_collective", False) or kind == "collective")
                print(
                    f"[nncase-triton] begin function={function_name} ordinal={ordinal} kind={kind} op={op_name} "
                    f"logical_pe_dispatch<pe_count={pe_count}, collective={collective}> "
                    f"args=[{args}] attrs={_verbose_format_attrs(attrs)}",
                    flush=True)
                return {"start": time.perf_counter(), "function": function_name, "ordinal": ordinal, "kind": kind, "op": op_name}

            def _verbose_launch_end(event):
                if event is None:
                    return
                elapsed_ms = (time.perf_counter() - event["start"]) * 1000.0
                print(
                    f"[nncase-triton] end function={event['function']} ordinal={event['ordinal']} "
                    f"kind={event['kind']} op={event['op']} elapsed_ms={elapsed_ms:.3f}",
                    flush=True)

            def _execute_launch(kind, op_name, context, argument_names, separate, launch_meta):
                if context.get("_suppress_launch_verbose"):
                    return _execute_launch_body(kind, op_name, context, argument_names, separate, launch_meta)
                event = _verbose_launch_begin(context, kind, op_name, argument_names, launch_meta)
                try:
                    return _execute_launch_body(kind, op_name, context, argument_names, separate, launch_meta)
                finally:
                    _verbose_launch_end(event)

            def _execute_launch_body(kind, op_name, context, argument_names, separate, launch_meta):
                context["current_launch_metadata"] = launch_meta or {}
                attrs = (launch_meta or {}).get("op_attrs", {})
                native = _try_execute_triton_native_launch(kind, op_name, context, argument_names, launch_meta)
                if native is not _TRITON_NATIVE_UNSUPPORTED:
                    return native
                _require_native_triton_launch(kind, op_name)
                if op_name in ("memcopy", "tensor_load", "gather_reduce_scatter"):
                    return _copy_tensor(context, argument_names[0], argument_names[1])
                if op_name == "tensor_store":
                    return _copy_tensor(context, argument_names[1], argument_names[0])
                if op_name == "matmul":
                    return _run_matmul(context, argument_names, attrs)
                if op_name in ("softmax", "vectorized_softmax"):
                    return _run_softmax(context, argument_names, attrs)
                if op_name == "vectorized_layer_norm":
                    return _run_layer_norm(context, argument_names, attrs)
                if op_name == "gather":
                    return _run_gather(context, argument_names, attrs)
                if op_name == "transpose":
                    src = _get_tensor(context, argument_names[0])
                    out = _get_tensor(context, argument_names[1], src)
                    perm = attrs.get("perm")
                    result = src.permute(*perm).contiguous() if perm else _transpose_to_shape(src, out)
                    return _write_tensor(context, argument_names[1], result)
                if op_name in ("ro_pe", "rope"):
                    return _run_rope(context, argument_names)
                if op_name == "get_position_ids":
                    return _run_get_position_ids(context, argument_names)
                if op_name == "concat":
                    return _run_concat(context, argument_names, attrs)
                if op_name == "pack":
                    return _run_pack(context, argument_names, attrs)
                if op_name == "unpack":
                    return _run_unpack(context, argument_names, attrs)
                if op_name in ("update_paged_attention_kvcache", "update_paged_attention_kv_cache"):
                    return _run_update_kv(context, argument_names, attrs)
                if op_name == "paged_attention":
                    return _run_paged_attention(context, argument_names, attrs)
                if op_name == "swish":
                    torch = _require_torch()
                    x = _get_tensor(context, argument_names[0])
                    beta = float(attrs.get("beta", 1.0))
                    return _write_tensor(context, argument_names[1], x * torch.sigmoid(x * beta))
                if op_name.startswith("elementwise."):
                    torch = _require_torch()
                    if op_name == "elementwise.cast":
                        x = _get_tensor(context, argument_names[0])
                        dtype = _dtype_from_name(attrs.get("new_type", "DataTypes.Float32"))
                        return _write_tensor(context, argument_names[1], x.to(dtype))
                    if op_name == "elementwise.add":
                        return _write_tensor(context, argument_names[2], _get_tensor(context, argument_names[0]) + _get_tensor(context, argument_names[1]))
                    if op_name == "elementwise.mul":
                        return _write_tensor(context, argument_names[2], _get_tensor(context, argument_names[0]) * _get_tensor(context, argument_names[1]))
                    if op_name == "elementwise.where":
                        return _write_tensor(context, argument_names[3], torch.where(_get_tensor(context, argument_names[0]).bool(), _get_tensor(context, argument_names[1]), _get_tensor(context, argument_names[2])))
                    if op_name == "elementwise.compare.equal":
                        return _write_tensor(context, argument_names[2], _get_tensor(context, argument_names[0]) == _get_tensor(context, argument_names[1]))
                    if op_name == "elementwise.cos":
                        return _write_tensor(context, argument_names[1], torch.cos(_get_tensor(context, argument_names[0])))
                    if op_name == "elementwise.sin":
                        return _write_tensor(context, argument_names[1], torch.sin(_get_tensor(context, argument_names[0])))
                raise NotImplementedError(f"unsupported CUDA/Triton launch {kind}:{op_name} args={argument_names}")

            def _entry_begin(function_meta, function_args):
                if not function_meta.get("is_entry"):
                    return
                _KV_STATE["entry_depth"] += 1
                if _KV_STATE["entry_depth"] == 1 and function_args:
                    seq_len = int(function_args[0][1][0]) if isinstance(function_args[0], tuple) and len(function_args[0]) >= 2 else 0
                    _KV_STATE["current_start"] = int(_KV_STATE.get("total_tokens", 0))
                    _KV_STATE["current_length"] = seq_len

            def _entry_end(function_meta):
                if not function_meta.get("is_entry"):
                    return
                if _KV_STATE["entry_depth"] == 1:
                    _KV_STATE["total_tokens"] = int(_KV_STATE.get("total_tokens", 0)) + int(_KV_STATE.get("current_length", 0))
                _KV_STATE["entry_depth"] = max(0, _KV_STATE["entry_depth"] - 1)

            """);
    }

    public string BuildMetadataJson(CudaTritonModuleSource module)
        => BuildMetadataJson(module, planComputeCclTails: true);

    private string BuildMetadataJson(CudaTritonModuleSource module, bool planComputeCclTails)
    {
        if (planComputeCclTails)
        {
            module = CudaComputeCclTailPlanner.Plan(module);
        }

        var dataPoolSize = module.Functions.Count == 0 ? 0 : module.Functions.Max(f => f.LocalDataPoolSize);
        var outputPoolSize = module.Functions.Count == 0 ? 0 : module.Functions.Max(f => f.OutputPoolSize);
        var blockLocalDataPoolSize = module.Functions.Count == 0 ? 0 : module.Functions.Max(f => f.BlockLocalDataPoolSize);
        var poolBytesPerPe = Max(
            dataPoolSize,
            outputPoolSize,
            module.RdataPoolSize,
            module.ThreadLocalRdataPoolSize,
            module.BlockLocalRdataPoolSize,
            blockLocalDataPoolSize);
        var cclScratchBytes = CudaComputeCclTailPlanner.GetScratchBytes(module);
        var sb = new StringBuilder();
        sb.AppendLine("{");
        sb.AppendLine("  \"schema_version\": 1,");
        sb.AppendLine("  \"device_id\": 0,");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"pe_count\": {module.PeCount},");
        sb.AppendLine($"  \"fused_kernel\": {Quote(NTTTargetOptions.FormatCudaFusedKernelMode(module.FusedKernelMode))},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"pool_bytes_per_pe\": {poolBytesPerPe},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"ccl_scratch_bytes\": {cclScratchBytes},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"data_pool_size\": {dataPoolSize},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"output_pool_size\": {outputPoolSize},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"rdata_pool_size\": {module.RdataPoolSize},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"thread_local_rdata_pool_size\": {module.ThreadLocalRdataPoolSize},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"block_local_rdata_pool_size\": {module.BlockLocalRdataPoolSize},");
        sb.AppendLine(CultureInfo.InvariantCulture, $"  \"block_local_data_pool_size\": {blockLocalDataPoolSize},");
        sb.AppendLine($"  \"function_ids\": {{{string.Join(", ", module.Functions.Select(f => $"{Quote(f.Name)}: {f.Id.ToString(CultureInfo.InvariantCulture)}"))}}},");
        sb.AppendLine("  \"functions\": [");
        for (int i = 0; i < module.Functions.Count; i++)
        {
            var function = module.Functions[i];
            sb.AppendLine("    {");
            sb.AppendLine(CultureInfo.InvariantCulture, $"      \"id\": {function.Id},");
            sb.AppendLine($"      \"name\": {Quote(function.Name)},");
            sb.AppendLine($"      \"is_entry\": {JsonBool(function.IsEntry)},");
            sb.AppendLine($"      \"parameters\": [{string.Join(", ", function.Parameters.Select(Quote))}],");
            sb.AppendLine($"      \"parameter_descriptors\": {BuildParameterDescArray(function.ParameterDescs)},");
            sb.AppendLine($"      \"buffers\": {BuildBufferMap(function.Buffers)},");
            sb.AppendLine(CultureInfo.InvariantCulture, $"      \"data_pool_size\": {function.LocalDataPoolSize},");
            sb.AppendLine(CultureInfo.InvariantCulture, $"      \"output_pool_size\": {function.OutputPoolSize},");
            sb.AppendLine(CultureInfo.InvariantCulture, $"      \"rdata_pool_size\": {function.RdataPoolSize},");
            sb.AppendLine(CultureInfo.InvariantCulture, $"      \"block_local_data_pool_size\": {function.BlockLocalDataPoolSize},");
            sb.AppendLine($"      \"returns\": {BuildReturnDescArray(function.Returns)},");
            sb.AppendLine("      \"launches\": [");
            for (int j = 0; j < function.Launches.Count; j++)
            {
                var launch = function.Launches[j];
                sb.Append("        {");
                sb.Append(CultureInfo.InvariantCulture, $"\"ordinal\": {launch.Ordinal}, ");
                sb.Append($"\"kind\": {Quote(ToPythonKind(launch.Kind))}, ");
                sb.Append($"\"op_name\": {Quote(launch.OpName)}, ");
                sb.Append($"\"arguments\": [{string.Join(", ", launch.Arguments.Select(Quote))}], ");
                sb.Append($"\"buffer_arguments\": {BuildBufferMap(launch.BufferArguments)}, ");
                sb.Append($"\"op_attrs\": {BuildAttributeMap(launch.OpAttributes)}, ");
                sb.Append($"\"requires_collective\": {JsonBool(launch.RequiresCollective)}");
                sb.Append('}');
                sb.AppendLine(j == function.Launches.Count - 1 ? string.Empty : ",");
            }

            sb.AppendLine("      ]");
            sb.Append("    }");
            sb.AppendLine(i == module.Functions.Count - 1 ? string.Empty : ",");
        }

        sb.AppendLine("  ]");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private static void WriteLaunchHelper(StringBuilder sb, string kind)
    {
        sb.AppendLine($"def _launch_{kind}(op_name, context, argument_names, separate=False, launch_meta=None):");
        sb.AppendLine($"    return _record_launch({Quote(kind)}, op_name, context, argument_names, separate, launch_meta)");
        sb.AppendLine();
    }

    private static void WriteFunctionInvoker(StringBuilder sb, CudaTritonFunctionSource function)
    {
        var invokerName = GetInvokerName(function.Name);
        var orderedLaunches = function.Launches.OrderBy(l => l.Ordinal).ToArray();
        var isShapeBucketEntry = function.IsEntry
            && orderedLaunches.Length > 1
            && orderedLaunches.All(l => l.Kind == CudaTritonLaunchKind.Function && l.OpName.StartsWith("main_segment_", StringComparison.Ordinal));
        sb.AppendLine($"def {invokerName}(pe_id, data_pool, output_pool, rdata_pool, *function_args, stream=None, all_data_pools=None, all_output_pools=None, all_rdata_pools=None, block_local_rdata_pool=None, all_block_local_rdata_pools=None, ccl_scratch_pool=0, ccl_scratch_bytes=0):");
        sb.AppendLine($"    function_meta = _get_function_metadata({function.Id.ToString(CultureInfo.InvariantCulture)})");
        sb.AppendLine("    context = _make_context(pe_id, data_pool, output_pool, rdata_pool, function_args, stream, function_meta, all_data_pools, all_output_pools, all_rdata_pools, block_local_rdata_pool, all_block_local_rdata_pools, ccl_scratch_pool, ccl_scratch_bytes)");
        sb.AppendLine($"    _bind_function_args(context, [{string.Join(", ", function.Parameters.Select(Quote))}], function_args)");
        sb.AppendLine("    _entry_begin(function_meta, function_args)");
        sb.AppendLine("    try:");
        if (isShapeBucketEntry)
        {
            sb.AppendLine($"        _selected_shape_bucket_ordinal = _select_shape_bucket_launch(function_meta, [{string.Join(", ", orderedLaunches.Select(l => l.Ordinal.ToString(CultureInfo.InvariantCulture)))}], int(_symbol_env(context).get(\"sequence_length\", 0)))");
            sb.AppendLine("        _shape_bucket_matched = False");
            foreach (var launch in orderedLaunches)
            {
                sb.AppendLine($"        if _selected_shape_bucket_ordinal == {launch.Ordinal.ToString(CultureInfo.InvariantCulture)}:");
                sb.AppendLine("            _shape_bucket_matched = True");
                sb.AppendLine($"            _launch_{ToPythonKind(launch.Kind)}({Quote(launch.OpName)}, context, [{string.Join(", ", launch.Arguments.Select(Quote))}], separate={ToPythonBool(launch.RequiresCollective)}, launch_meta=_get_launch_metadata(function_meta, {launch.Ordinal.ToString(CultureInfo.InvariantCulture)}))");
            }

            sb.AppendLine("        if not _shape_bucket_matched:");
            sb.AppendLine("            raise KeyError(f\"unknown CUDA/Triton shape bucket ordinal: {_selected_shape_bucket_ordinal}\")");
        }
        else
        {
            foreach (var launch in orderedLaunches)
            {
                sb.AppendLine($"        _launch_{ToPythonKind(launch.Kind)}({Quote(launch.OpName)}, context, [{string.Join(", ", launch.Arguments.Select(Quote))}], separate={ToPythonBool(launch.RequiresCollective)}, launch_meta=_get_launch_metadata(function_meta, {launch.Ordinal.ToString(CultureInfo.InvariantCulture)}))");
            }
        }

        sb.AppendLine("        return context");
        sb.AppendLine("    finally:");
        sb.AppendLine("        _entry_end(function_meta)");
        sb.AppendLine();
    }

    private static void WriteDispatch(StringBuilder sb, IReadOnlyList<CudaTritonFunctionSource> functions)
    {
        sb.AppendLine("def launch(function_id, pe_id, data_pool, output_pool, rdata_pool, *function_args, stream=None, all_data_pools=None, all_output_pools=None, all_rdata_pools=None, block_local_rdata_pool=None, all_block_local_rdata_pools=None, ccl_scratch_pool=0, ccl_scratch_bytes=0):");
        if (functions.Count == 0)
        {
            sb.AppendLine("    raise KeyError(f\"unknown cuda triton function id: {function_id}\")");
            return;
        }

        sb.AppendLine("    if all_data_pools is not None and len(all_data_pools) > 1:");
        sb.AppendLine("        if int(pe_id) != 0:");
        sb.AppendLine("            return None");
        sb.AppendLine("        return _execute_multi_pe_function(function_id, *function_args, stream=stream, all_data_pools=all_data_pools, all_output_pools=all_output_pools, all_rdata_pools=all_rdata_pools, all_block_local_rdata_pools=all_block_local_rdata_pools, ccl_scratch_pool=ccl_scratch_pool, ccl_scratch_bytes=ccl_scratch_bytes)");
        foreach (var function in functions)
        {
            sb.AppendLine($"    if function_id == {function.Id.ToString(CultureInfo.InvariantCulture)}:");
            sb.AppendLine($"        return {GetInvokerName(function.Name)}(pe_id, data_pool, output_pool, rdata_pool, *function_args, stream=stream, all_data_pools=all_data_pools, all_output_pools=all_output_pools, all_rdata_pools=all_rdata_pools, block_local_rdata_pool=block_local_rdata_pool, all_block_local_rdata_pools=all_block_local_rdata_pools, ccl_scratch_pool=ccl_scratch_pool, ccl_scratch_bytes=ccl_scratch_bytes)");
        }

        sb.AppendLine("    raise KeyError(f\"unknown cuda triton function id: {function_id}\")");
    }

    private static string GetInvokerName(string functionName) => $"invoke_{SanitizeIdentifier(functionName)}";

    private static string SanitizeIdentifier(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            return "unnamed";
        }

        var sb = new StringBuilder(value.Length);
        for (int i = 0; i < value.Length; i++)
        {
            var ch = value[i];
            sb.Append(char.IsLetterOrDigit(ch) || ch == '_' ? ch : '_');
        }

        if (char.IsDigit(sb[0]))
        {
            sb.Insert(0, '_');
        }

        return sb.ToString();
    }

    private static string ToPythonKind(CudaTritonLaunchKind kind) => kind switch
    {
        CudaTritonLaunchKind.Compute => "compute",
        CudaTritonLaunchKind.Memcopy => "memcopy",
        CudaTritonLaunchKind.Boxing => "boxing",
        CudaTritonLaunchKind.Reduce => "reduce",
        CudaTritonLaunchKind.Matmul => "matmul",
        CudaTritonLaunchKind.Collective => "collective",
        CudaTritonLaunchKind.Function => "function",
        _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, null),
    };

    private static string ToPythonBool(bool value) => value ? "True" : "False";

    private static string JsonBool(bool value) => value ? "true" : "false";

    private static ulong Max(params ulong[] values) => values.Max();

    private static string BuildParameterDescArray(IReadOnlyList<CudaTritonFunctionParameterDesc>? parameters)
    {
        if (parameters == null || parameters.Count == 0)
        {
            return "[]";
        }

        return $"[{string.Join(", ", parameters.Select(BuildParameterDesc))}]";
    }

    private static string BuildParameterDesc(CudaTritonFunctionParameterDesc parameter)
    {
        var parts = new List<string>
        {
            $"{Quote("name")}: {Quote(parameter.Name)}",
        };
        if (parameter.Type != null)
        {
            parts.Add($"{Quote("type")}: {Quote(parameter.Type)}");
        }

        if (parameter.Buffer != null)
        {
            parts.Add($"{Quote("buffer")}: {Quote(parameter.Buffer)}");
        }

        return $"{{{string.Join(", ", parts)}}}";
    }

    private static string BuildReturnDescArray(IReadOnlyList<CudaTritonReturnDesc>? returns)
    {
        if (returns == null || returns.Count == 0)
        {
            return "[]";
        }

        return $"[{string.Join(", ", returns.Select(BuildReturnDesc))}]";
    }

    private static string BuildReturnDesc(CudaTritonReturnDesc ret)
    {
        return $"{{{Quote("index")}: {ret.Index.ToString(CultureInfo.InvariantCulture)}, {Quote("value")}: {Quote(ret.Value)}, {Quote("buffer")}: {BuildBufferDesc(ret.Buffer)}}}";
    }

    private static string BuildBufferMap(IReadOnlyDictionary<string, CudaTritonBufferDesc>? buffers)
    {
        if (buffers == null || buffers.Count == 0)
        {
            return "{}";
        }

        return $"{{{string.Join(", ", buffers.OrderBy(kv => kv.Key, StringComparer.Ordinal).Select(kv => $"{Quote(kv.Key)}: {BuildBufferDesc(kv.Value)}"))}}}";
    }

    private static string BuildBufferDesc(CudaTritonBufferDesc buffer)
    {
        var parts = new List<string>
        {
            $"{Quote("name")}: {Quote(buffer.Name)}",
            $"{Quote("dtype")}: {Quote(buffer.DType)}",
            $"{Quote("element_size_bytes")}: {buffer.ElementSizeBytes.ToString(CultureInfo.InvariantCulture)}",
            $"{Quote("rank")}: {buffer.Rank.ToString(CultureInfo.InvariantCulture)}",
            $"{Quote("shape")}: [{string.Join(", ", buffer.Shape.Select(BuildDimDesc))}]",
            $"{Quote("strides")}: [{string.Join(", ", buffer.Strides.Select(BuildStrideDesc))}]",
            $"{Quote("memory")}: {BuildMemoryDesc(buffer.Memory)}",
        };

        if (buffer.DistributedType != null)
        {
            parts.Add($"{Quote("distributed_type")}: {Quote(buffer.DistributedType)}");
        }

        return $"{{{string.Join(", ", parts)}}}";
    }

    private static string BuildMemoryDesc(CudaTritonMemoryDesc memory)
    {
        var parts = new List<string>
        {
            $"{Quote("location")}: {Quote(memory.Location)}",
            $"{Quote("hierarchy")}: {memory.Hierarchy.ToString(CultureInfo.InvariantCulture)}",
            $"{Quote("alignment")}: {memory.Alignment.ToString(CultureInfo.InvariantCulture)}",
            $"{Quote("buffer_size_bytes")}: {BuildDimDesc(memory.BufferSizeBytes)}",
            $"{Quote("span_start_bytes")}: {BuildDimDesc(memory.SpanStartBytes)}",
            $"{Quote("span_size_bytes")}: {BuildDimDesc(memory.SpanSizeBytes)}",
            $"{Quote("base_start")}: {BuildNullableString(memory.BaseStart)}",
        };
        return $"{{{string.Join(", ", parts)}}}";
    }

    private static string BuildDimDesc(CudaTritonDimDesc dim)
    {
        var parts = new List<string>
        {
            $"{Quote("kind")}: {Quote(dim.Kind)}",
        };
        if (dim.Value.HasValue)
        {
            parts.Add($"{Quote("value")}: {dim.Value.Value.ToString(CultureInfo.InvariantCulture)}");
        }

        if (dim.Symbol != null)
        {
            parts.Add($"{Quote("symbol")}: {Quote(dim.Symbol)}");
        }

        if (dim.Expression != null)
        {
            parts.Add($"{Quote("expression")}: {Quote(dim.Expression)}");
        }

        return $"{{{string.Join(", ", parts)}}}";
    }

    private static string BuildStrideDesc(CudaTritonStrideDesc stride)
        => BuildDimDesc(new CudaTritonDimDesc(stride.Kind, stride.Value, stride.Symbol, stride.Expression));

    private static string BuildAttributeMap(IReadOnlyDictionary<string, object?>? attributes)
    {
        if (attributes == null || attributes.Count == 0)
        {
            return "{}";
        }

        return $"{{{string.Join(", ", attributes.OrderBy(kv => kv.Key, StringComparer.Ordinal).Select(kv => $"{Quote(kv.Key)}: {BuildJsonValue(kv.Value)}"))}}}";
    }

    private static string BuildJsonValue(object? value) => value switch
    {
        null => "null",
        string s => Quote(s),
        bool b => JsonBool(b),
        byte b => b.ToString(CultureInfo.InvariantCulture),
        sbyte b => b.ToString(CultureInfo.InvariantCulture),
        short s => s.ToString(CultureInfo.InvariantCulture),
        ushort s => s.ToString(CultureInfo.InvariantCulture),
        int i => i.ToString(CultureInfo.InvariantCulture),
        uint i => i.ToString(CultureInfo.InvariantCulture),
        long l => l.ToString(CultureInfo.InvariantCulture),
        ulong l => l.ToString(CultureInfo.InvariantCulture),
        float f => float.IsFinite(f) ? f.ToString("R", CultureInfo.InvariantCulture) : Quote(f.ToString(CultureInfo.InvariantCulture)),
        double d => double.IsFinite(d) ? d.ToString("R", CultureInfo.InvariantCulture) : Quote(d.ToString(CultureInfo.InvariantCulture)),
        decimal d => d.ToString(CultureInfo.InvariantCulture),
        CudaTritonDimDesc dim => BuildDimDesc(dim),
        CudaTritonStrideDesc stride => BuildStrideDesc(stride),
        CudaTritonMemoryDesc memory => BuildMemoryDesc(memory),
        CudaTritonBufferDesc buffer => BuildBufferDesc(buffer),
        IReadOnlyDictionary<string, object?> map => BuildAttributeMap(map),
        IEnumerable enumerable => $"[{string.Join(", ", enumerable.Cast<object?>().Select(BuildJsonValue))}]",
        _ => Quote(value.ToString() ?? string.Empty),
    };

    private static string BuildNullableString(string? value) => value == null ? "null" : Quote(value);

    private static string Quote(string value)
    {
        var escaped = value
            .Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", "\\r", StringComparison.Ordinal)
            .Replace("\n", "\\n", StringComparison.Ordinal);
        return $"\"{escaped}\"";
    }
}
